(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/poems-0029.js"] = [{"id":"poem-bd63e7a2b50f60335505aa28","title":"挽汪帅参  其二","author":"王柏","dynasty":"宋","verses":["世路艰危极，人情政可叹。","未闻亲子在，而有外邪干。","轩冕多为累，箪瓢未必寒。","此皆身外事，且閟一丘安。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-edea3968-3cfe-42ad-a006-7228eee87fe4","tags":[]},{"id":"poem-bd736a40f521613e33d7243e","title":"兵要望江南 占六壬第二十八（京本列第十七○四十五首） 三十四","author":"易静","dynasty":"唐","verses":["三刑内，最恶是天罡。","或是季兮为日上，冲加四煞必相伤，夜即恐惊忙（京本作「亡」。","魁罡临日，主大将死，临辰，主小将死，日辰俱临，俱死。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-284653cc-cc67-4c0f-afbb-0db0e95a12d8","tags":[]},{"id":"poem-bd73cee455fb403e51eaeb63","title":"同前","author":"无名氏《张协状元》","dynasty":"元","verses":["细寻思常怒起。","(合)因它后丧一女儿。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2734","tags":[]},{"id":"poem-bd952f60b717c9f0555c67e7","title":"永遇乐·薰风解愠","author":"柳永","dynasty":"宋","verses":["薰风解愠，昼景清和，新霁时候。","火德流光，萝图荐祉，累庆金枝秀。","璇枢绕电，华渚流虹，是日挺生元后。","缵唐虞垂拱，千载应期，万灵敷祐。","殊方异域，争贡琛賮，架𪩘航波奔凑。","三殿称觞，九仪就列，韶頀锵金奏。","藩侯瞻望彤庭，亲携僚吏，竞歌元首。","祝尧龄、北极齐尊，南山共久。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-115","tags":[]},{"id":"poem-bd99fca8eb9cc493c5e2c196","title":"水调歌头·题西山秋爽图","author":"纳兰性德","dynasty":"清","verses":["空山梵呗静，水月影俱沉。","悠然一境人外，都不许尘侵。","岁晚忆曾游处，犹记半竿斜照，一抹界疏林。","绝顶茅庵里，老衲正孤吟。","云中锡，溪头钓，涧边琴。","此生著几两屐，谁识卧游心？","准拟乘风归去，错向槐安回首，何日得投簪。","布袜青鞋约，但向画图寻。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-111","tags":[]},{"id":"poem-bd9fedf338b32d397a7c8816","title":"咏笔二首 一","author":"徐夤","dynasty":"唐","verses":["秦代将军欲建功，截龙搜兔助英雄。","用多谁念毛皆拔，抛却更嫌心不中。","史氏只应归道直，江淹何独偶灵通。","班超握管不成事，投掷翻从万里戎。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-c9324b0c-06db-4ba1-bb4e-3471eeab042e","tags":[]},{"id":"poem-bda0de71d6efbf85c770404f","title":"黄鹤楼","author":"崔颢","dynasty":"唐","verses":["昔人已乘黄鹤去，此地空余黄鹤楼。","黄鹤一去不复返，白云千载空悠悠。","晴川历历汉阳树，芳草萋萋鹦鹉州。","日暮乡关何处是，烟波江上使人愁。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-黃鶴樓","tags":[]},{"id":"poem-bda4fe657c3b11dcb41faac5","title":"谒圣林","author":"杨文郁","dynasty":"唐","verses":["悠悠往古继来今，天地无穷照孔林。","两到金丝堂下拜，门生无负百年心。","（见《宋诗纪事补遗》卷二引《阙里志》。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-0de2d1e7-ca75-4aba-8d24-94a1cc0859fd","tags":[]},{"id":"poem-bdb22b390029deb3e4c4ca92","title":"句  其三","author":"司马光","dynasty":"宋","verses":["藏阄新度腊，习舞竞裁衣。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-dca6d512-67c9-4eb4-9651-b9902e4e85e9","tags":[]},{"id":"poem-bdb8e4e4a7edb0ac10d9ec57","title":"酬秦系山人题赠","author":"皎然","dynasty":"唐","verses":["云林出空乌未归，松吹时飘雨浴衣。","石语花愁徒自诧，吾心见境尽为非。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-9419fd9a-b053-4d34-9fc5-4350e10e473c","tags":[]},{"id":"poem-bdc068b88ae18348cf4e6644","title":"舟中贻赵野云之官三衢","author":"释居简","dynasty":"宋","verses":["笑君吟似饮中歌，船贴清溪翠卷罗。","梦枕熟时忺昼永，午阴团影得凉多。","官非奉礼宁如贺，家岂杨州旧姓何。","试问柯山棋一局，不知曾烂几人柯。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-359c5f42-0273-4b20-9e8d-23d1b7104374","tags":[]},{"id":"poem-bdc17fbe31711fd1e2af06dd","title":"句  其二","author":"刘望之","dynasty":"宋","verses":["地连巴楚峰岚见，节近清明柳色知。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-daa08ac3-2b8e-4713-ad8f-66842dcd7140","tags":[]},{"id":"poem-bdc89e01486ab6d27ac3d6a2","title":"过梅里七首  家于无锡四十载今敝庐数堵犹存今列题于后 忆西湖双㶉𫛶","author":"李绅","dynasty":"唐","verses":["双㶉𫛶，锦毛斓斑长比翼，戏绕莲藂回锦臆。","照灼花丛两相得，渔歌惊起飞南北。","缭绕追随不迷惑，云间上下同栖息。","不作惊禽远相忆，东家少妇机中语。","剪断回文泣机杼，徒嗟孔雀衔毛羽。","一去东南别离苦，五里裴回竟何补。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-38869ec6-7ab2-4c91-b1b1-6772267fdf63","tags":["西湖"]},{"id":"poem-bdccc92f53f68500424f2936","title":"唐大飨拜洛乐章 显和","author":"则天皇后","dynasty":"唐","verses":["顾德有慙虚菲，明祇屡降祯符。","汜水初呈秘象，温洛荐表昌图。","玄泽流恩载洽，丹襟荷渥增愉。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-396fd7fa-de45-48e7-b379-0937f6429019","tags":[]},{"id":"poem-bdd12ab60dcd9b60469e7aa9","title":"酬隐珪舍人寄红烛","author":"郑畋","dynasty":"唐","verses":["蜜炬殷红画不如，且将归去照吾庐。","今来并得三般事，灵运诗篇逸少书。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-97b16580-163e-4807-9a76-846468bfe735","tags":[]},{"id":"poem-bdd24b409479c9d476046e38","title":"次韵无为使君尊兄见寄之什","author":"张栻","dynasty":"宋","verses":["江山接境相望近，风雨一春音问疎。","安得从公苕霅上，幅巾一叶卧看书。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-0be92060-f7b9-469a-8b63-94df6b436d21","tags":[]},{"id":"poem-bdd52aea406aba48337c67d0","title":"句 千秋节应制","author":"陆坚","dynasty":"唐","verses":["风移覃土宇，云上浃群臣。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-f9e4128d-2ed0-4356-917c-ca2e67d4a0bb","tags":[]},{"id":"poem-bddadbb57259848151048d6b","title":"声声慢·寻寻觅觅","author":"李清照","dynasty":"宋","verses":["寻寻觅觅，冷冷清清，凄凄惨惨戚戚。","乍暖还寒时候，最难将息。","三杯两盏淡酒，怎敌他、晚来风急。","雁过也，正伤心，却是旧时相识。","满地黄花堆积。","憔悴损，如今有谁摘。","守著窗儿，独自怎生得黑。","梧桐更兼细雨，到黄昏、点点滴滴。","这次第，怎一个、愁字了得。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-204","tags":["宋词三百首"]},{"id":"poem-bde2561c124f9b48baaae5ee","title":"旱鱼词上苗相公","author":"姚鹄","dynasty":"唐","verses":["似龙鳞已足，唯是欠登门。","日里腮犹湿，泥中目未昏。","乞锄防蚁穴，望水泻金盆。","他日能为雨，公田报此恩。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-83520070-449b-4362-bddf-708f5038024f","tags":[]},{"id":"poem-bde2b0d2996cebd28905810e","title":"秋夜玩月怀玉霄道士","author":"贯休","dynasty":"唐","verses":["光异磨砻出，轮非雕斵成。","今宵刚道别，举世勿人争。","征妇砧添怨，诗人哭到明。","惟宜华顶叟，笙磬有余声。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-f797c58f-66fc-4824-b457-fd739470ce47","tags":[]},{"id":"poem-bde8b4f2e24086e422aa773d","title":"采桑子·非关癖爱轻模样","author":"纳兰性德","dynasty":"清","verses":["非关癖爱轻模样，冷处偏佳。","别有根芽，不是人间富贵花。","谢娘别后谁能惜，飘泊天涯。","寒月悲笳，万里西风瀚海沙。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-88","tags":[]},{"id":"poem-bded71dff8438eca01dfc4bc","title":"四时四首 秋","author":"梅窗","dynasty":"宋","verses":["小雨凉添夜，兰芬润袭衣。","晓屏山曲曲，长若梦思归。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-fb30276b-60c5-4491-addf-65d757a2f803","tags":[]},{"id":"poem-bdf4619b4840516ea2c0badc","title":"怀匡山山长二首 一","author":"贯休","dynasty":"唐","verses":["白石峰之半，先生好在么。","卷帘当大瀑，常恨不如他。","杉罅龙涎溢，潭㘭石发多。","吾皇搜草泽，争奈谢安何。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-b350d17b-8e23-4042-bf63-9f5900f59be1","tags":["庐山"]},{"id":"poem-bdfce3cfae6a70d2370539fd","title":"山坡羊","author":"施惠《幽闺记》","dynasty":"元","verses":["(生)娘子，我病体难医难治，你这苦如何存济？(旦)原流恩降福，降福灾星退。","(生)势渐危，料应我不久矣！若还我死，你必选个高门配，我便死向黄泉，一心只念你。","(旦)休提。","不由人泪暗垂。","伤悲，何时得归故里？。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-3001","tags":[]},{"id":"poem-be077dbb50df567eb5cc034a","title":"却望无锡芙蓉湖 五","author":"李绅","dynasty":"唐","verses":["翠崖幽谷分明处，倦鸟归云在眼前。","惆怅白头为四老，远随尘土去伊川。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-b924d86f-d84d-4c54-bec9-25877fc9eafa","tags":[]},{"id":"poem-be15b5e5421c0b58759d5093","title":"寻刘处士","author":"皇甫曾","dynasty":"唐","verses":["几年人不见，林下掩柴关。","留客当清夜，逢君话旧山。","隔城寒杵急，带月早鸿还。","南陌虽相近，其如隐者闲。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-803b76e6-7aed-4569-88a8-7cd6c5b74c6a","tags":[]},{"id":"poem-be2a5b47c489e92cab27c4ad","title":"春思","author":"皇甫冉","dynasty":"唐","verses":["莺啼燕语报新年，马邑龙堆路几千。","家住秦城邻汉苑，心随明月到胡天。","机中锦字论长恨，楼上花枝笑独眠。","为问元戎窦车骑，何时反斾勒燕然。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-d35f583a-c20c-453c-a886-e13f98b2e4b4","tags":["唐诗三百首","思念","七言律诗","春天","妇女","闺怨"]},{"id":"poem-be2fc436cb558d74a59d60d8","title":"汉宫春·潇洒江梅","author":"李邴","dynasty":"宋","verses":["潇洒江梅，向竹梢疏处，横两三枝。","东君也不爱惜，雪压霜欺。","无情燕子，怕春寒、轻失花期。","却是有，年年塞雁，归来曾见开时。","清浅小溪如练，问玉堂何似，茅舍疏篱。","伤心故人去后，冷落新诗。","微云淡月，对江天、分付他谁。","空自忆，清香未减，风流不在人知。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-108","tags":["宋词三百首"]},{"id":"poem-be3279590784d77e17eb665f","title":"青玉案·年来减却风情大","author":"史浩","dynasty":"宋","verses":["年来减却风情大。","百样收心待不作。","恰恨仙翁停画舸。","雪中把酒，美人频为，浅破樱桃颗。","清歌谁许阳春和。","悄不放、遥空片云过。","惊落梁尘浑可可。","一声啭处，故园春近，桃李还知么。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-64","tags":[]},{"id":"poem-be33c987d2c71ea5680fcb27","title":"同崔邠登鹳雀楼","author":"李益","dynasty":"唐","verses":["鹳雀楼西百尺樯，汀洲云树共茫茫。","汉家箫鼓空流水，魏国山河半夕阳。","事去千年犹恨速，愁来一日即为长。","风烟倂起思归望，远目非春亦自伤。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-2bf81ba1-a18f-4e42-9bad-ac68cae86da4","tags":[]},{"id":"poem-be401ac1e66491cb6436bfa8","title":"与胡居士皆病寄此诗兼示学人二首 一","author":"王维","dynasty":"唐","verses":["一兴微尘念，横有朝露身。","如是覩阴界，何方置我人。","碍有固为主，趣空宁舍宾。","洗心讵悬解，悟道正迷津。","因爱果生病，从贪始觉贫。","色声非彼妄，浮幻即吾真。","四达竟何遣，万殊安可尘。","胡生但高枕，寂寞与谁邻。","战胜不谋食，理齐甘负薪。","予若未始异，讵论疎与亲。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-0bebdd6d-6adb-42aa-9bc3-d3cf41c45687","tags":[]},{"id":"poem-be426ac0f79aac3f25291902","title":"题通明堂","author":"陈造","dynasty":"宋","verses":["世儒困墙面，窒外由蔽中。","一理有朝澈，八窗自玲珑。","公无末俗病，人识古贤风。","照物鉴绝尘，与世云行空。","似闻虚白室，略与公心同。","彼哉坏陂老，史语宁所蒙。","吾知泚笔意，千载端为公。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-b97a9a9d-ebba-4ea0-8a78-d7f080d6fade","tags":[]},{"id":"poem-be42ed47061be7fb1894cba1","title":"九章·涉江","author":"屈原","dynasty":"先秦","verses":["余幼好此奇服兮，年既老而不衰。","带长铗之陆离兮，冠切云之崔嵬，被明月兮佩宝璐。","世混浊而莫余知兮，吾方高驰而不顾。","驾青虬兮骖白螭，吾与重华游兮瑶之圃。","登昆仑兮食玉英，与天地兮同寿，与日月兮同光。","哀南夷之莫吾知兮，旦余济乎江湘。","乘鄂渚而反顾兮，欸秋冬之绪风。","步余马兮山皋，邸余车兮方林。","乘舲船余上沅兮，齐吴榜以击汰。","船容与而不进兮，淹回水而疑滞。","朝发枉渚兮，夕宿辰阳。","苟余心其端直兮，虽僻远之何伤。","入溆浦余儃徊兮，迷不知吾所如。","深林杳以冥冥兮，猿狖之所居。","山峻高以蔽日兮，下幽晦以多雨。","霰雪纷其无垠兮，云霏霏而承宇。","哀吾生之无乐兮，幽独处乎山中。","吾不能变心而从俗兮，固将愁苦而终穷。","接舆髡首兮，桑扈臝行。","忠不必用兮，贤不必以。","伍子逢殃兮，比干菹醢。","与前世而皆然兮，吾又何怨乎今之人！","余将董道而不豫兮，固将重昏而终身！","乱曰：鸾鸟凤皇，日以远兮。","燕雀乌鹊，巢堂坛兮。","露申辛夷，死林薄兮。","腥臊并御，芳不得薄兮。","阴阳易位，时不当兮。","怀信佗傺，忽乎吾将行兮！"],"enabled":true,"collection":"楚辞","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/楚辞/chuci.json#record-14","tags":[]},{"id":"poem-be5138f6ce6457df76581b03","title":"千秋岭下","author":"赵嘏","dynasty":"唐","verses":["知有岩前万树桃，未逢摇落思空劳。","年年盛发无人见，三十六溪春水高。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-41a1eea7-0cd8-415f-9dec-91638ecaa5b4","tags":[]},{"id":"poem-be531e01857f6d937e1fcdd9","title":"登兖州城楼","author":"杜甫","dynasty":"唐","verses":["东郡趋庭日，南楼纵目初。","浮云连海岱，平野入青徐。","孤嶂秦碑在，荒城鲁殿余。","从来多古意，临眺独踌躇。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-登兗州城樓","tags":[]},{"id":"poem-be562ea7c9ed752aa199bf48","title":"清明日赐百僚新火","author":"史延","dynasty":"唐","verses":["上苑连侯第，清明及暮春。","九天初改火，万井属良辰。","颁赐恩逾洽，承时庆自均。","翠烟和柳嫩，红焰出花新。","宠命尊三老，祥光烛万人。","太平当此日，空复荷陶甄。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-732defb7-3b46-41cb-b01f-6b77a1bb875b","tags":[]},{"id":"poem-be5f1e8fc6ba77655cac99a1","title":"兵要望江南 《周易》占候第二十六（三十七首） 五","author":"易静","dynasty":"唐","verses":["凡占《易》，先论六亲方。","大煞彼乡（辛本、川本作「大谨五乡」）比和尅，应杀世主总漂扬，官鬼子孙量。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-a29d7015-b8e2-4609-a997-eb5d1c3f8b17","tags":[]},{"id":"poem-be7a910fa6af6e1647efd4f6","title":"霜天晓角·春云粉色","author":"高观国","dynasty":"宋","verses":["春云粉色。","春水和云湿。","试问西湖杨柳，东风外、几丝碧。","望极。","连翠陌。","兰桡双桨急。","欲访莫愁何处，旗亭在、画桥侧。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-388","tags":["西湖"]},{"id":"poem-be8137618a9a9e575f498be6","title":"过贾浪仙旧地","author":"李洞","dynasty":"唐","verses":["鹤外唐来有谪星，长江东注冷沧溟。","境搜松雪仙人岛，吟歇林泉主簿厅。","片月已能临榜黑，遥天何益抱坟青。","年年谁不登高第，未胜骑驴入画屏。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-196eb93d-e3f5-4537-8efd-da5f8f6b03a1","tags":["长江"]},{"id":"poem-be81de62af86f4ff88cdb27e","title":"至德中赠内兄刘赞","author":"卢纶","dynasty":"唐","verses":["时难访亲戚，相见喜还悲。","好学年空在，从戎事已迟。","听琴泉落处，步履雪深时。","惆怅多边信，青山共有期。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-82a9fe1c-3f19-4351-9b6a-13d690a366ed","tags":[]},{"id":"poem-be896dcbaf740e6b10362a95","title":"南园十三首 一","author":"李贺","dynasty":"唐","verses":["花枝草蔓眼中开，小白长红越女腮。","可怜日暮嫣香落，嫁与春风不用媒。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-6766c804-9532-42e3-b85d-d0d4d8bccecf","tags":[]},{"id":"poem-be8c4209d39c51cda307795f","title":"苦战行","author":"杜甫","dynasty":"唐","verses":["苦战身死马将军，自云伏波之子孙。","干戈未定失壮士，使我叹恨伤精魂。","去年江南讨狂贼，临江把臂再难得。","别时孤云今不飞，时独看云泪横臆。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-30658953-4fd6-4433-9d53-632ddbdd6113","tags":[]},{"id":"poem-be8d28e144e345ee30e9e340","title":"幽渚云","author":"丘为","dynasty":"唐","verses":["漠漠云在渚，无心去何从。","（「何」下原卷衍「疑」字。","）青连晚湖色，澹起秋烟客（容）[一]。","（「客」，原卷作「容」，与王校合。","）渡水上下白，归山深浅重，来为巫峡女，去逐葛川龙。","勿为长幽滞，当飞第一峰。","（[一]依王仲闻先生校。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-4752656e-b251-4f41-bc2c-f0ebbc5171f0","tags":[]},{"id":"poem-be95639bcdb5cc0b2e0000b2","title":"前腔","author":"施惠《幽闺记》","dynasty":"元","verses":["(小旦)他须是瑞莲亲兄。","(旦)呀！原来是令兄。","为何散失了！(小旦)为军马犯阙。","(旦)是，我晓得了。","散失忙寻相应者，那时节只争个字儿差迭。","妹子，和你比先前又亲，自今越更着疼热，你休随着我跟脚，久已后是我男儿那枝叶。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-3074","tags":[]},{"id":"poem-bea06e86d5aea8e29ba99d0e","title":"送同年郑祥先辈归汉南","author":"赵嘏","dynasty":"唐","verses":["年来惊喜两心知，高处同攀次第枝。","人倚绣屏闲赏夜，马嘶花径醉归时。","声名本是文章得，藩阃曾劳笔砚随。","家去恩门四千里，只应从此梦旌旗。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-2347547e-3d3e-42a4-a21d-b5719416ae18","tags":[]},{"id":"poem-bea090b69ec9afc8c8023ad5","title":"谢制帅高卿剡四首  其一","author":"陈造","dynasty":"宋","verses":["宰邑非良才，朴拙瞢信己。","曾无补毫发，粗不畏首尾。","倚公造物手，袭璧护玷毁。","世有百谪余，观旁首重稽。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-0cefc552-b615-4b6d-b02a-21344b0686ff","tags":[]},{"id":"poem-bea75236cc9e432fa1fce703","title":"六么令","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["连枝异木，见这坟台，兔走如驯。","禽虫草木尚怀仁，这一封诏，必因君。","(合)料天也会相怜悯，料天也会相怜悯。","(生唱)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5272","tags":[]},{"id":"poem-bea9de976eab385ee77ee470","title":"八月灯夕寄游越施秀才","author":"徐凝","dynasty":"唐","verses":["四天净色寒如水，八月清辉冷似霜。","想得越人今夜见，孟家珠在镜中央。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-3ceefec8-ea4d-4e8d-9059-9a35acdfa91c","tags":[]},{"id":"poem-beb46a9832dba23c3af5c104","title":"吕宣徽挽歌二首  其二","author":"司马光","dynasty":"宋","verses":["维岳人皆仰，长城众所依。","远猷方克壮，昭世忽长违。","象设俨如在，英灵窅不归。","唯应令名久，竹素蔼余辉。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-8af179ec-743d-4098-8987-ea92e2f63b5e","tags":[]},{"id":"poem-bebc609748a7714bdcee3b34","title":"漫书五首 一","author":"司空图","dynasty":"唐","verses":["长拟求闲未得闲，又劳行役出秦关。","逢人渐觉乡音异，却恨莺声似故山。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-266f1bd0-a44c-4bbf-b64d-d626e5ebe52e","tags":[]},{"id":"poem-bec5884605e5c87dc3049e29","title":"诗寄赠四明宝云通法师（二首） 一","author":"钱俶","dynasty":"唐","verses":["海角复天涯，形分道不赊。","灯清读圜觉，香煖顶袈裟。","戒比珠无类（疑当作「颣」），心犹镜断瑕。","平生赖慈眼，南望一咨嗟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-def76611-0863-48cb-ae5e-ec01e455e0ab","tags":[]},{"id":"poem-bec73333689d89f29da30ee7","title":"题米芾山水","author":"赵文","dynasty":"宋","verses":["远山浓淡几无影，远树高低略带行。","不是糢糊并纸败，无人知是米元章。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-d9875849-1625-49ff-85c4-003ad8c47535","tags":[]},{"id":"poem-becc231fb829a563730dd079","title":"蓦山溪·新正初破","author":"欧阳修","dynasty":"宋","verses":["新正初破，三五银蟾满。","纤手染香罗，剪红莲、满城开遍。","楼台上下，歌管咽春风，驾香轮，停宝马，只待金乌晚。","帝城今夜，罗绮谁为伴。","应卜紫姑神，问归期、相思望断。","天涯情绪，对酒且开颜，春宵短。","春寒浅。","莫待金杯暖。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-737","tags":[]},{"id":"poem-bed0198fd78253de27457fd3","title":"祀雨师乐章 奠币登歌","author":"包佶","dynasty":"唐","verses":["岁正朱明，礼布玄制。","惟乐能感，与神合契。","阴雾离披，灵驭摇裔。","膏泽之庆，期于稔岁。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-dfe6bbaa-2b5f-4aed-94a1-b23a41960a48","tags":[]},{"id":"poem-bed20b79eb9bb54de6229910","title":"立可则礼思复雪中见过","author":"释居简","dynasty":"宋","verses":["花翻云叶舞风回，新好缤缤带雨开。","团破小龙寒未瀹，客如两鹤瘦飞来。","白灰宿火虽同拥，黄独无苗各自煨。","苕霅扁舟明日去，小须门外玉山颓。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-bb824203-4a3f-4e71-9be4-d8ceb0452e3c","tags":[]},{"id":"poem-bed23dff241c606bb0f8e664","title":"次韵赵漕  其二","author":"张栻","dynasty":"宋","verses":["雨声历历来庭户，喜色津津到泽虞。","击壤径思同野老，名亭讵敢学坡苏。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-dde68da4-3268-4b81-a520-754d80bdcfad","tags":[]},{"id":"poem-bed3a04a7aa7c2eb4665e662","title":"题终南麻先生寂禅师石室","author":"刘得仁","dynasty":"唐","verses":["因居石室贫，五十二回春。","拥褐冥心客，穷经暮齿人。","翠沈空水定，雨绝片云新。","危细秋峰径，相随到顶频。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-69e6771a-9618-4817-a98b-63bae08e606d","tags":[]},{"id":"poem-beda3f0ea853361e062b94db","title":"题筹笔驿","author":"殷潜之","dynasty":"唐","verses":["江东矜割据，邺下夺孤嫠。","霸畧非匡汉，宏图欲佐谁。","奏书辞后主，仗劒出全师。","重袭襃斜路，悬开反正旗。","欲将苞有截，必使举无遗。","沈虑经谋际，挥毫决胜时。","圜觚当分画，前箸此操持。","山秀扶英气，川流入妙思。","算成功在彀，运去事终亏。","命屈天方厌，人亡国自随。","艰难推旧姓，开创极初基。","总叹曾过地，宁探作教资。","若归新历数，谁复顾衰危。","报德兼明道，长留识者知。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-e6aec2d8-b762-419f-905f-8e2029dfc90f","tags":[]},{"id":"poem-bedad148495f48ae740e73b9","title":"送远客","author":"张籍","dynasty":"唐","verses":["南原相送处，秋水草还生。","同作忆乡客，如今分路行。","因谁寄归信，渐远问前程。","明日重阳节，无人上古城。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-8a772176-3c27-442a-9fe6-5b44ed42423a","tags":[]},{"id":"poem-bedc8d9534e9efc7bbc6f145","title":"有感","author":"王柏","dynasty":"宋","verses":["岁月飘零事转乖，未能凭酒放眉开。","萧萧棠棣悲离黍，寂寞芝兰閟野莱。","生计半随豪气坏，放心犹傍圣经回。","秋来旱势滔滔远，谁念苍生正可哀。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-6220cf34-503b-4942-bc59-83daa201dc61","tags":[]},{"id":"poem-bee77c3e20aacb08da014750","title":"寄柏学士林居","author":"杜甫","dynasty":"唐","verses":["自胡之反持干戈，天下学士亦奔波。","叹彼幽栖载典籍，萧然暴露依山阿。","青山万里静散地，白雨一洗空垂萝。","乱代飘零余到此，古人成败子如何。","荆扬春冬异风土，巫峡日夜多云雨。","赤叶枫林百舌鸣，黄泥野岸天鸡舞。","盗贼纵横甚密迩，形神寂莫甘辛苦。","几时高议排金门，各使苍生有环堵。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-797a6309-5f6b-47f3-80e7-d83142478dd6","tags":[]},{"id":"poem-beec9db8ac1e0f4a2f52e78e","title":"游越溪","author":"郑绍","dynasty":"唐","verses":["溪水碧悠悠，猨声断客愁。","渔潭逢钓楫，月浦值孤舟。","访泊随烟火，迷途视斗牛。","今宵越乡意，还取醉忘忧。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-2237386f-91db-4f62-9103-fec2c5791d81","tags":[]},{"id":"poem-bef70da02f25cc6584401a0a","title":"折桂令","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["燕沈檀香喷金猊，昭告灵魂，听剖因依。","自从俺宴罢瑶池，宫袍宠赐，相府勒赘。","掩只为撇不下糟糠旧妻，苦推辞桃杏新室，致受磨折，改调俺在潮阳。","妻，因此上耽误了恁的归期。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8271","tags":[]},{"id":"poem-bef83659366e4543905bef5b","title":"九怀·危俊","author":"王褒","dynasty":"汉","verses":["林不容兮鸣蜩，余何留兮中州？","陶嘉月兮总驾，搴玉英兮自修。","结荣茝兮逶逝，将去烝兮远游。","径岱土兮魏阙，历九曲兮牵牛。","聊假日兮相佯，遗光燿兮周流。","望太一兮淹息，纡余辔兮自休。","晞白日兮皎皎，弥远路兮悠悠。","顾列孛兮缥缥，观幽云兮陈浮。","钜宝迁兮砏磤，雉咸雊兮相求。","泱莽莽兮究志，惧吾心兮㤽㤽。","步余马兮飞柱，览可与兮匹俦。","卒莫有兮纤介，永余思兮怞怞。"],"enabled":true,"collection":"楚辞","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/楚辞/chuci.json#record-40","tags":[]},{"id":"poem-bf0ec5e434e197fea17ca9e5","title":"浣溪沙·十里湖光载酒游","author":"纳兰性德","dynasty":"清","verses":["十里湖光载酒游，青帘低映白苹洲。","西风听彻采菱讴。","沙岸有时双袖拥，画船何处一竿收。","归来无语晚妆楼。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-135","tags":[]},{"id":"poem-bf11768d10f9adc555b1992f","title":"采桑子·红英一树春来早","author":"晏殊","dynasty":"宋","verses":["红英一树春来早，独占芳时。","我有心期。","把酒攀条惜绛蕤。","无端一夜狂风雨，暗落繁枝。","蝶怨莺悲。","满眼春愁说向谁。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-463","tags":[]},{"id":"poem-bf132c9eb830506b728c8b79","title":"和王明府见寄","author":"徐铉","dynasty":"宋","verses":["时情世难消我道，薄宦流年厄此身。","莫叹京华同寂寞，曾经兵革共漂沦。","对山开户唯求静，贳酒留宾不道贫。","善政空多尚淹屈，不知谁是解忧民。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-38f4583c-0514-4fb8-aae0-e4517a197428","tags":[]},{"id":"poem-bf1f2a934c7bac4e43cc60b2","title":"乞宽禅师瘿山罍呈宣供奉","author":"李益","dynasty":"唐","verses":["石色凝秋藓，峰形若夏云。","谁留秦苑地，好赠杏溪君。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-60d8de49-e393-4470-bae6-6a7ce35c5d29","tags":[]},{"id":"poem-bf266f716136324dc3c1e301","title":"菩萨蛮·罗裾薄薄秋波染","author":"魏承班","dynasty":"五代","verses":["罗裾薄薄秋波染，眉间画时山两点。","相见绮筵时，深情暗共知。","翠翘云鬓动，敛态弹金凤。","宴罢入兰房，邀入解佩珰。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-8-juan.json#record-48","tags":[]},{"id":"poem-bf300cd99231e9fecb6d8c55","title":"宿邯郸馆寄马磁州","author":"张籍","dynasty":"唐","verses":["孤客到空馆，夜寒愁卧迟。","虽沽主人酒，不似在家时。","几宿得欢笑，如今成别离。","明朝行更远，回望隔山陂。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-c05cbcb0-dd20-4466-945d-160774bc39bf","tags":[]},{"id":"poem-bf31f4b5538ae44402725c55","title":"晚过吴伯承留饮","author":"张栻","dynasty":"宋","verses":["推门野路竹毵毵，落日天寒相对谈。","可是主人风韵别，自斟白酒擘黄柑。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-750276ac-b649-447b-b70a-286d30e7be02","tags":[]},{"id":"poem-bf346d90b773fd1099cd7b55","title":"赠率子连  其一","author":"王祜","dynasty":"宋","verses":["下瞰虚空临绝涧，上排烟雾倚山颠。","四边险绝无猿鸟，独卧深云三十年。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-24f5540d-3515-4a3d-bec4-d20804fef514","tags":[]},{"id":"poem-bf3728dac748f844f90c92df","title":"前腔","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["［外］这财礼虽是轻微，你为何讲是说非？婆子，你不晓得，那王秀才是个读书人，一朝显达，名登高第，那其间夫荣妻贵。","这财礼呵，纵轻微，既来之，且宜安之。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8070","tags":[]},{"id":"poem-bf398e9d0b7808a91027e9e9","title":"少年游·去年同醉","author":"向子𬤇","dynasty":"宋","verses":["去年同醉，酴醿花下，健笔赋新词。","今年君去，酴醿欲破，谁与醉为期。","旧曲重歌倾别酒，风露泣花枝。","章水能长湘水远，流不尽、两相思。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-116","tags":[]},{"id":"poem-bf4006b06190d9e0253921cc","title":"六州歌头·长怀望断","author":"张孝祥","dynasty":"宋","verses":["长怀望断，关塞莽然平。","征尘暗，霜风劲，悄边声。","黯销凝。","追想当年事，殆天数，非人力，洙泗上，弦歌地，亦膻腥。","隔水毡乡，落日牛羊下，区脱纵横。","看名王宵猎，骑火一川明。","笳鼓悲鸣。","遣人惊。","念腰间箭，匣中剑，空埃蠹，竟何成。","时易失，心徒壮，岁将零。","渺神京。","干羽方怀远，静烽燧，且休兵。","冠盖使，纷驰骛，若为情。","闻道中原遗老，常南望，羽葆霓旌。","使行人到此，忠愤气填膺。","有泪如倾。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-278","tags":["宋词三百首"]},{"id":"poem-bf4172e1aaabb606b8897aa7","title":"一剪梅","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["浪暖桃香欲化鱼，期逼春闱，诏赴春闱。","郡中空有辟贤书，心恋亲闱，难舍亲闱。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-4929","tags":[]},{"id":"poem-bf509bef8a6af3f762152eee","title":"浣溪沙·翡翠屏开绣幄红","author":"张泌","dynasty":"五代","verses":["翡翠屏开绣幄红，谢娥无力晓妆慵，锦帷鸳被宿香浓。","微雨小庭春寂寞，燕飞莺语隔帘栊，杏花凝恨倚东风。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-4-juan.json#record-31","tags":[]},{"id":"poem-bf56f7b93c804a3d2061fe0a","title":"郡侯坐上观琉璃瓶中游鱼","author":"徐夤","dynasty":"唐","verses":["宝器一泓银汉水，锦鳞才动即先知。","似涵明月波宁隔，欲上轻冰律未移。","薄雾罩来分咫尺，碧绡笼处较毫厘。","文翁未得沈香饵，拟置金盘召左慈。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-5a83e700-8951-469d-ba56-5be416c33d45","tags":[]},{"id":"poem-bf59f1e381eee85d4e0eaf8a","title":"终衮","author":"无名氏《张协状元》","dynasty":"元","verses":["似鸾凤和鸣，相应青云际。","效鹣鹣比翼，鸳鸯双双戏。","相怜相爱，拼尽老，与偎随。","待把伊，托在心儿里。","(末)神歌鬼舞，况我们村落皆欢喜，愿厮守终久于飞。","(合)身赴月宫折桂枝，已两两同欢会，这些滋味美。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2546","tags":[]},{"id":"poem-bf5a29f12f36f3c05b3ba7ea","title":"减字木兰花·柳塘微雨","author":"米友仁","dynasty":"宋","verses":["柳塘微雨。","两两飞鸥来复去。","倚遍重阑。","人在碧云山外山。","一春离怨。","日照绮窗长几线。","酒病情魔。","两事春来无奈何。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-49","tags":[]},{"id":"poem-bf5a82b657bb8ad756a0f0a0","title":"尚书郎上直闻春漏","author":"周彻","dynasty":"唐","verses":["建礼通华省，含香直紫宸。","静闻铜史漏，暗识桂宫春。","滴沥疑将绝，清泠发更新。","寒声临鴈沼，疎韵应鸡人。","迥入千门彻，行催五夜频。","高台闲自听，非是驻征轮。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-c0837426-530d-494d-aa6f-65251b567723","tags":[]},{"id":"poem-bf5bcc86cfa7bd56c3c09f42","title":"偈 十六","author":"契此","dynasty":"唐","verses":["白屋安贫终暂计，夕阳归路岂知还？","莲花佛国深深处，出世芳踪不可攀。","（《奉化县补义志》卷三。","）（按：《明州岳林寺志》六卷，奉化戴明琮撰成于康熙二十六年。","《奉化县补义志》十卷，民国元年蒋尧裳撰。","二书均藏于奉化县文物室，承张靖龙同志录示。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-3f7e6ebe-0c83-4513-b185-dbc951bbc8ee","tags":[]},{"id":"poem-bf69d05ed08c9f05233d674b","title":"驾幸圣容院应制","author":"广宣","dynasty":"唐","verses":["大唐国里千年圣，王舍城中百亿身。","却指容颜非我相，自言空色是吾真。","深殿虔心随宝辇，广庭徐步引金轮。","古来贵重缘亲近，狂客慙为侍从臣。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-6ccbaef5-6d1e-456c-8a04-204bf22852e0","tags":[]},{"id":"poem-bf74d7ee2bd94b0b77e9878a","title":"玉交枝","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["［旦］音容不见，望冥中听奴诉言，甫离怀抱娘恩断，目应怎瞑黄泉。","谁知继母心太偏，逼奴改嫁相凌贱。","我那亲娘，孩儿今日出嫁，本待做一碗羹饭与你，料他决不相容。","苦！莫说羹饭，我要痛哭一场，［合］怕他们闻之见嫌，只得且吞声泪痕如线。","我的亲娘在日，岂是今日？。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8091","tags":[]},{"id":"poem-bf77adc4135bd8328d4cd0b8","title":"宗脉颂","author":"文偃","dynasty":"唐","verses":["如来一大事，出现于世间。","五千方便教，流传几百年。","四十九年说，未曾忤出言。","如来灭度后，付嘱迦叶边。","西天二十八，祖佛印相传。","达摩观东土，五叶气相连。","九年来面壁，唯有吃茶言。","二祖为上首，达摩廻西天。","六祖曹溪住，衣钵后不传。","派分三五六，各各达真源。","七八心忙乱，空花坠目前。","苦哉●眼士，认得止啼钱。","外道多毁谤，弟子得生天。","昔在灵山上，今日获安然。","六门俱休歇，无心处处闲。","如有玄中客，但除入我山。","一味醍醐药，万病悉皆安。","因缘契会者，无心便安禅。","（以上十三首均见《祖堂集》卷十一）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-5e099ad0-904b-437c-b6b1-8e0016080145","tags":[]},{"id":"poem-bf7a1e00b7b11366904df941","title":"驾幸三会寺应制","author":"上官昭容","dynasty":"唐","verses":["释子谈经处，轩臣刻字留。","故台遗老识，残简圣皇求。","驻跸怀千古，开襟望九州。","四山缘塞合，二水夹城流。","宸翰陪瞻仰，天杯接献酬。","太平词藻盛，长愿纪鸿休。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-3f1f308b-60d8-4cd0-987b-a8c0d02801cd","tags":[]},{"id":"poem-bf7d54532082fc668e9d3fdf","title":"淡黄柳·咏柳","author":"纳兰性德","dynasty":"清","verses":["三眠未歇，乍到秋时节。","一树料阳蝉更咽，曾绾灞陵离别。","絮己为萍风卷叶，空凄切。","长条莫轻折，苏小恨，倩他说。","尽飘零、游冶章台客。","红板桥空，湔裙人去，依旧晓风残月。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-142","tags":[]},{"id":"poem-bf8d6229a2b5b0d05e02fe1e","title":"兵要望江南 占六壬第二十八（京本列第十七○四十五首） 十三","author":"易静","dynasty":"唐","verses":["兵行次，四季狱神凶。","春卯（京本注：「夏午。","」）顺（京本注：「四季。","」）雷（京本作「来」）居震位，辰年艮（京本作「日辰年」）上忌相逢，临着失勋功。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-369b3459-b0b8-4a70-bff3-512c49cfcaf6","tags":[]},{"id":"poem-bf91a67e652465f15c1a7695","title":"即事三首  其三","author":"李纲","dynasty":"宋","verses":["森森榕木碧参天，夏日初闻第一蝉。","美荫羡君诚得计，何须凄怨嘒风前。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-4c8ea1df-5f49-4ccc-9e4e-d223fbce5e44","tags":[]},{"id":"poem-bf95361f279fc0cdaf5ab90f","title":"桑柔","author":"佚名","dynasty":"先秦","verses":["菀彼桑柔，其下侯旬，捋采其刘，瘼此下民。不殄心忧，仓兄填兮。倬彼昊天，宁不我矜？","四牡骙骙，旟旐有翩。乱生不夷，靡国不泯。民靡有黎，具祸以烬。于乎有哀，国步斯频。","国步灭资，天不我将。靡所止疑，云徂何往？君子实维，秉心无竞。谁生厉阶，至今为梗？","忧心殷殷，念我土宇。我生不辰，逢天𫢸怒。自西徂东，靡所定处。多我觏痻，孔棘我圉。","为谋为毖，乱况斯削。告尔忧恤，诲尔序爵。谁能执热，逝不以濯？其何能淑，载胥及溺。","如彼溯风，亦孔之僾。民有肃心，荓云不逮。好是稼穑，力民代食。稼穑维宝，代食维好？","天降丧乱，灭我立王。降此蟊贼，稼穑卒痒。哀恫中国，具赘卒荒。靡有旅力，以念穹苍。","维此惠君，民人所瞻。秉心宣犹，考慎其相。维彼不顺，自独俾臧。自有肺肠，俾民卒狂。","瞻彼中林，甡甡其鹿。朋友已谮，不胥以谷。人亦有言：进退维谷。","维此圣人，瞻言百里。维彼愚人，覆狂以喜。匪言不能，胡斯畏忌？","维此良人，弗求弗迪。维彼忍心，是顾是复。民之贪乱，宁为荼毒。","大风有隧，有空大谷。维此良人，作为式谷。维彼不顺，征以中垢。","大风有隧，贪人败类。听言则对，诵言如醉。匪用其良，复俾我悖。","嗟尔朋友，予岂不知而作。如彼飞虫，时亦弋获。既之阴女，反予来赫。","民之罔极，职凉善背。为民不利，如云不克。民之回遹，职竞用力。","民之未戾，职盗为寇。凉曰不可，覆背善詈。虽曰匪予，既作尔歌！"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-256","tags":[]},{"id":"poem-bf984d4b169e6a9b0962514b","title":"病后游青龙寺","author":"李端","dynasty":"唐","verses":["病来形貌秽，斋沫入东林。","境静闻神远，身羸向道深。","芭蕉高自折，荷叶大先沈。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-64ab14be-6565-4ac9-aa39-4a9e40d92023","tags":[]},{"id":"poem-bf98b87d4fa90431e9a3cab6","title":"点绛唇·何处君家","author":"毛滂","dynasty":"宋","verses":["何处君家，蟠桃花下瑶池畔。","日迟烟暖。","占得春长远。","几见花开，一任年光换。","今年见。","明年重见。","春色如人面。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-852","tags":[]},{"id":"poem-bf9fec4741b65d9df362e7f6","title":"玄都观桃花","author":"刘禹锡","dynasty":"唐","verses":["紫陌红尘拂面来，无人不道看花回。","玄都观里桃千树，尽是刘郎去后栽。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-玄都觀桃花","tags":[]},{"id":"poem-bfa3fd8306a60f6d544dc573","title":"诗九首托南剑刘教寻亦周墓焚之  其八","author":"赵文","dynasty":"宋","verses":["怕看杜老怀观颖，厌见东坡说子由。","每读渠诗先掩卷，旁人怪我泪双流。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-9643f66f-ccb6-4d49-bd50-10288d99c1f1","tags":[]},{"id":"poem-bfaa0c4891f8dfc2a18b1710","title":"杜少府之任蜀州","author":"王勃","dynasty":"唐","verses":["城阙辅三秦，风烟望五津。","与君离别意，同是宦游人。","海内存知己，天涯若比隣。","无为在岐路，儿女共沾巾。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-fe6f4b72-855c-43b9-8883-8b3fe3cd8bd4","tags":["唐诗三百首","八年级下册(课外)","友情","送别","初中古诗","五言律诗","哲理"]},{"id":"poem-bfada229e091f450942d8105","title":"清明","author":"孙永","dynasty":"宋","verses":["每年每遇清明节，把酒寻花特地忙。","今日江头衰病起，神前新火一炉香。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-cbdc20e8-889d-45e6-97a1-86e0638baae3","tags":[]},{"id":"poem-bfb055064c87badf4c80cfb8","title":"寿安西渡奉别郑相公 二","author":"孟郊","dynasty":"唐","verses":["东都清风减，君子西归朝。","独抱岁晏恨，泗吟不成谣。","贵游意多味，贱别情易消。","回鴈忆前叫，浪凫念后漂。","悠悠孤飞景，耸耸衔霜条。","昧趣多滞涩，嬾朋寡新僚。","病深理方悟，悔至心自烧。","寂静道何在，忧勤学空饶。","乃知减闻见，始遂情逍遥。","文字徒营织，声华谅疑骄。","顾慙耕稼士，朴略气韵调。","善士有余食，佳畦冬生苗。","养人在养身，此旨清如韶。","愿贡高古言，敢望锡类招。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-fda6f87b-62dd-4806-ad1e-857856352d36","tags":[]},{"id":"poem-bfb49beb0faaa0dce2f1c43a","title":"过梁震居留题","author":"罗隐","dynasty":"唐","verses":["道院迎仙客，书堂隐相儒。","庭栽栖凤竹，池养化龙鱼。","（见《尧山堂外纪》卷三九、《全浙诗话》卷八。","）（按：隐卒开平间，震至后康时始在荆南握重权。","诗疑出伪托。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-83252864-bba3-4423-bff1-fa54fca51573","tags":[]},{"id":"poem-bfba7462ecf81908bef01db7","title":"恭禧皇太后挽歌词三首 一","author":"薛能","dynasty":"唐","verses":["八月曾殊选，三星固异仪。","祔陵经灞浐，归赗杂华夷。","旌去题新谥，宫存鏁素帏。","重泉应不恨，生见太平时。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-f71ef698-2204-4c30-9ee2-f9dcebb80ed4","tags":[]},{"id":"poem-bfc8ce53f7f7cf077dc78659","title":"渐渐之石","author":"佚名","dynasty":"先秦","verses":["渐渐之石，维其高矣。山川悠远，维其劳矣。武人东征，不遑朝矣。","渐渐之石，维其卒矣。山川悠远，曷其没矣？武人东征，不遑出矣。","有豕白蹢，烝涉波矣。月离于毕，俾滂沱矣。武人东征，不皇他矣。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-231","tags":[]},{"id":"poem-bfd5b2077e82e0a49ff5b6a9","title":"陪致政开府太师留守相公致政内翰燕集輙歌盛美为三公寿皆用公字为韵 内翰","author":"司马光","dynasty":"宋","verses":["眉似高僧秀，颜如童子红。","忠纯汲长孺，高洁夏黄公。","矫矫辽东鸖，冥冥塞北鸿。","自夸新酒量，像想百分空。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-07191555-db39-4e8e-be4e-96db1fefc4ce","tags":[]},{"id":"poem-bfd6842e10c1e4682ef2b17f","title":"句  其二","author":"韩缜","dynasty":"宋","verses":["唐蒙谕巴蜀，通道至卭僰。","列郡徼西南，夷居半岩壁。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-5e898937-5299-41fe-b3be-e56f9ac3b7d4","tags":[]},{"id":"poem-bfdb7ff046d1ceffe2bb5554","title":"忆寿春废虎坑余以春二月至郡主吏举所职称霍山多虎每岁采茶为患择肉于人至春常修陷穽数十所勒猎者采其皮睛余悉除罢之是岁虎不复为害至余去郡三载","author":"李绅","dynasty":"唐","verses":["匪将履尾求兢惕，那效探雏所患争。","当路绝群尝诫暴，为猫驱狝亦先迎。","每推至化宣余力，岂用潜机害尔生。","休逐豺狼止贪戾，好为仁兽答皇明。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-e0b629da-76cc-4223-98b8-25fad7f63656","tags":[]},{"id":"poem-bfe0189586c6932765dbdf6b","title":"同陈宰黄簿游灵山八首宰云吾辈可谓忙里偷闲苦中作乐以八字为韵  其六","author":"陈造","dynasty":"宋","verses":["名山吾敢忘，独往兴易穷。","胜游得胜士，杖屦凛生风。","表表益者友，当求古人中。","今世习凿齿，前身黄石公。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-1e7f3078-dcbf-45cb-a652-f1e7af167ad6","tags":[]},{"id":"poem-bfe30083c464efcaa278bc2e","title":"蝶恋花·小院深深门掩亚","author":"欧阳修","dynasty":"宋","verses":["小院深深门掩亚。","寂寞珠帘，画阁重重下。","欲近禁烟微雨罢。","绿杨深处秋千挂。","傅粉狂游犹未舍。","不念芳时，眉黛无人画。","薄幸未归春去也。","杏花零落香红谢。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-642","tags":[]},{"id":"poem-bfec00919f54d07cc501db89","title":"别川道士","author":"释了惠","dynasty":"宋","verses":["尘中相见头颅别，座上交谈语笑同。","拶到了无同别处，擎拳合掌各西东。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-4485e00f-ec94-4671-97d9-2ae993ffe04f","tags":[]},{"id":"poem-bff04f796f3bca398e6c3077","title":"偈颂六十七首  其三五","author":"释原妙","dynasty":"宋","verses":["身贫道贫，无法可亲。","一味盲枷瞎棒，闻者见者莫不生嗔。","黄金自有黄金价，终不和沙卖与人。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-b8d01b35-2289-44eb-abbe-b2fb83069251","tags":[]},{"id":"poem-bff426ef34fd31b059c7fa51","title":"拥鼻吟・吴音子·别酒初销","author":"贺铸","dynasty":"宋","verses":["别酒初销，怃然弭棹蒹葭浦。","回首不见高城，青楼更何许。","大艑轲峨，越商巴贾。","万恨龙锺，篷下对语。","指征路。","山缺处，孤烟起，历历闻津鼓。","江豚吹浪，晚来风转夜深雨。","拥鼻微吟，断肠新句。","粉碧罗笺，封泪寄与。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-55","tags":[]},{"id":"poem-bff9bcd158266fc9d7e59f9c","title":"同前换头","author":"无名氏《张协状元》","dynasty":"元","verses":["听启：自来不识恁底，平日我衣冠济济。","(旦)没奈何风云际会时，应是胜如今日。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2514","tags":[]},{"id":"poem-bffb4ac533f8b6df3828a52e","title":"望鹤林寺","author":"李绅","dynasty":"唐","verses":["鹤栖峰下青莲宇，花发江城世界春。","红照日高殷夺火，紫凝霞曙莹销尘。","每思载酒悲前事，欲问题诗想旧身。","自叹秋风劳物役，白头拘束一闲人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-2041eb8c-12af-4d50-a54a-43cc1414f9eb","tags":[]},{"id":"poem-c00e395366a66ecccd75215f","title":"偈颂七十一首  其三六","author":"释了惠","dynasty":"宋","verses":["火种深埋冷寂中，几回拨著煖烘烘。","不知将谓吹嘘力，元是东君信息通。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-3589d06f-44b6-4a35-b96c-cf757b81ae3e","tags":[]},{"id":"poem-c010b86327ea810fd2fa47da","title":"醉扶归","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["我钉缘结发曾相共，难道是无缘对面不相逢？我凤枕驾衾也和他同，到凭兔毫茧纸将他功。","休休，毕竟一齐分付与东风，把往事也如春梦。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5215","tags":[]},{"id":"poem-c015bc372d7c10d2d0cd86cd","title":"浣溪沙·风递残香出绣帘","author":"孙光宪","dynasty":"五代","verses":["风递残香出绣帘，团窠金凤舞襜襜，落花微雨恨相兼。","何处去来狂太甚，空推宿酒睡无厌，怎教人不别猜嫌。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-7-juan.json#record-43","tags":[]},{"id":"poem-c017724bd3ab571b99611ed2","title":"临江仙·新月低垂帘额","author":"向子𬤇","dynasty":"宋","verses":["新月低垂帘额，小梅半出檐牙。","高堂开燕静无哗。","麟孙凤女，学语正咿呀。","宝鼎剩熏沈水，琼彝烂醉流霞。","芗林同老此生涯。","一川风露，总道是仙家。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-137","tags":[]},{"id":"poem-c01fe024d97e19e504583275","title":"送仪州李太保丈","author":"苏颂","dynasty":"宋","verses":["持节出西𬮱，腰章入旧秦。","家传虎韬术，朝有象贤人。","合闭关山月，帷褰渭水春。","虏尘今向息，正是雅歌辰。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-62d80140-6a0e-4283-816c-33e5099340ae","tags":[]},{"id":"poem-c0220a3288bbcdc57ee284d0","title":"促织","author":"张乔","dynasty":"唐","verses":["念尔无机自有情，迎寒辛苦弄梭声。","椒房金屋何曾识，偏向贫家壁下鸣。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-dfa1699d-1936-42d7-bb1c-716ced12fdb2","tags":[]},{"id":"poem-c02c0bbab67e01cf27f3a72c","title":"氓","author":"佚名","dynasty":"先秦","verses":["氓之蚩蚩，抱布贸丝。匪来贸丝，来即我谋。送子涉淇，至于顿丘。匪我愆期，子无良媒。将子无怒，秋以为期。","乘彼垝垣，以望复关。不见复关，泣涕涟涟。既见复关，载笑载言。尔卜尔筮，体无咎言。以尔车来，以我贿迁。","桑之未落，其叶沃若。于嗟鸠兮！无食桑葚。于嗟女兮！无与士耽。士之耽兮，犹可说也。女之耽兮，不可说也。","桑之落矣，其黄而陨。自我徂尔，三岁食贫。淇水汤汤，渐车帷裳。女也不爽，士二其行。士也罔极，二三其德。","三岁为妇，靡室劳矣。夙兴夜寐，靡有朝矣。言既遂矣，至于暴矣。兄弟不知，咥其笑矣。静言思之，躬自悼矣。","及尔偕老，老使我怨。淇则有岸，隰则有泮。总角之宴，言笑晏晏，信誓旦旦，不思其反。反是不思，亦已焉哉！"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-57","tags":[]},{"id":"poem-c0355f4ee6335d721aac3879","title":"浣溪沙·肠断班骓去未还","author":"纳兰性德","dynasty":"清","verses":["肠断班骓去未还，绣屏深锁凤箫寒。","一春幽梦有无间。","逗雨疏花浓淡改，关心芳草浅深难。","不成风月转摧残。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-58","tags":[]},{"id":"poem-c03a64fd137d5a81a1c96552","title":"薛廷范从事自宣城至因赠","author":"赵嘏","dynasty":"唐","verses":["少年从事霍嫖姚，来自枫林度柳桥。","金管别筵楼灼灼，玉溪回首马萧萧。","清风气调真君辈，知己风流满圣朝。","独有故人愁欲死，晚簷疎雨动空瓢。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-cc0602d8-7606-4e6f-a993-739027884900","tags":[]},{"id":"poem-c03fe9e4074dcb9708167bae","title":"永泰公主挽歌二首 一","author":"吴兢","dynasty":"唐","verses":["秾华从妇道，厘降适诸侯。","河汉天孙合，潇湘帝子游。","关雎方作训，鸣凤自相求。","可叹凌波迹，东川遂不流。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-77065e9d-4ee9-4937-bbad-fe9b901f3c6f","tags":[]},{"id":"poem-c062063eb5561413bd327818","title":"满庭芳·白玉楼高","author":"周邦彦","dynasty":"宋","verses":["白玉楼高，广寒宫阙，暮云如幛褰开。","银河一派，流出碧天来。","无数星躔玉李，冰轮动、光满楼台。","登临处，全胜瀛海，弱水浸蓬莱。","云鬟，香雾湿，月娥韵压，云冻江梅。","况餐花饮露，莫惜裴徊。","坐看人间如掌，山河影、倒入琼杯。","归来晚，笛声吹彻，九万里尘埃。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-501","tags":[]},{"id":"poem-c064ac2b734ae4459778ce16","title":"云安公主出降杂咏催粧二首 一","author":"陆畅","dynasty":"唐","verses":["天上琼花不避秋，今宵织女嫁牵牛。","万人惟待乘鸾出，乞巧齐登明月楼。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-751f96ce-ae00-4c17-b636-db5b09ee5554","tags":[]},{"id":"poem-c0666a05059ce0cb902b06ca","title":"夜月","author":"刘方平","dynasty":"唐","verses":["更深月色半人家，北斗阑干南斗斜。","今夜偏知春气暖，虫声新透绿窗纱。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-79e7ec6e-0d6c-4f95-8181-4671c42e1faf","tags":["唐诗三百首","月亮","春天","田园","九年级上册(课外)","中秋","初中古诗","七言绝句"]},{"id":"poem-c073348757359822582c55ba","title":"后庭花·越罗小袖新香蒨","author":"毛熙震","dynasty":"五代","verses":["越罗小袖新香蒨，薄笼金钏。","倚栏无语摇轻扇，半遮匀面。","春残日暖莺娇懒，满庭花片。","怎不教人长相见，画堂深院。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-x-juan.json#record-7","tags":[]},{"id":"poem-c074dbefcea173725cfce878","title":"酬友生早秋","author":"唐求","dynasty":"唐","verses":["彤云将欲罢，蝉柳响如秋。","雾散九霄近，日程三伏愁。","残阳宿雨霁，高浪碎沙沤。","袪足余旬后，分襟任自由。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-c0aace3b-defb-4eb2-98bd-bc2dcb6968af","tags":[]},{"id":"poem-c0751a18143b90d0a9468c2b","title":"河传·何处","author":"韦庄","dynasty":"五代","verses":["何处，烟雨，隋堤春暮。","柳色葱笼，画桡金缕，翠旗高飐香风，水光融。","青娥殿脚春妆媚，轻云里，绰约司花妓。","江都宫阙，清淮月映迷楼，古今愁。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-3-juan.json#record-4","tags":[]},{"id":"poem-c0757e79be93c403f7ed655f","title":"重阳日至峡道","author":"张籍","dynasty":"唐","verses":["无限青山行已尽，回看忽觉远离家。","逢高欲饮重阳酒，山菊今朝未有花。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-1da2720d-861f-482d-9931-e61480f4498c","tags":[]},{"id":"poem-c07d293ba20d62b24d41a260","title":"金陵览古 直渎","author":"朱存","dynasty":"宋","verses":["昼役人功夜鬼功，阳开阴阖几时终。","不闻掷土江中语，争得盈流一水通。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-ffd90226-e181-48d5-bbda-16811e5f9086","tags":[]},{"id":"poem-c0873c4739808bf5afb7ebc5","title":"郊庙歌辞 仪坤庙乐章 永和","author":"祝钦明","dynasty":"唐","verses":["閟宫实实，清庙微微。","降格无象，馨香有依。","式昭纂庆，方融嗣徽。","明禋是享，神保聿归。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-eed3132b-db96-48c9-aefc-898186012ccc","tags":[]},{"id":"poem-c08835fa0f702fbe0634cf37","title":"拟乐府子夜四时歌四首 二","author":"崔道融","dynasty":"唐","verses":["凉轩待月生，暗里萤飞出。","低回不称意，蛙鸣乱清瑟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-59ca0a52-e50f-43da-ad3b-a0eea7e4f03c","tags":[]},{"id":"poem-c097425617a0cd235dca4618","title":"水","author":"徐夤","dynasty":"唐","verses":["火性何如水性柔，西来东出几时休。","莫言通海能通汉，虽解浮舟也覆舟。","湘浦暮沈尧女怨，汾河秋泛汉皇愁。","洪波激湍归何处，二月桃花满眼流。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-0df790bb-c6f4-41f1-9215-3c3b08fe9702","tags":[]},{"id":"poem-c09a4c94a147cfe03006f180","title":"陶使君挽歌二首  其一","author":"徐铉","dynasty":"宋","verses":["太守今何在，行春去不归。","筵空收管吹，郊迥俨骖𬴂。","营外星才落，园中露已晞。","伤心梁上燕，犹解向人飞。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-19a4d427-64d3-4549-b762-313f4937ae81","tags":[]},{"id":"poem-c09ca63f9fabf48052da7899","title":"奉和九月九日登慈恩寺浮图应制","author":"郑愔","dynasty":"唐","verses":["涌霄开宝塔，倒影驻仙舆。","鴈子乘堂处，龙王起藏初。","秋风圣主曲，佳气史官书。","愿献重阳寿，承欢万岁余。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-d734f531-6626-4892-85b2-b1c9dd67ac85","tags":[]},{"id":"poem-c0a524d8b05419184a56cacc","title":"匏有苦叶","author":"佚名","dynasty":"先秦","verses":["匏有苦叶，济有深涉。深则厉，浅则揭。","有弥济盈，有鷕雉鸣。济盈不濡轨，雉鸣求其牡。","雍雍鸣雁，旭日始旦。士如归妻，迨冰未泮。","招招舟子，人涉卬否。不涉卬否，卬须我友。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-33","tags":[]},{"id":"poem-c0a6f9a1df72fd88ae44a98b","title":"赠别","author":"赵嘏","dynasty":"唐","verses":["水边秋草暮萋萋，欲驻残阳恨马蹄。","曾是管弦同醉伴，一声歌尽各东西。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-ba29023a-ed78-449a-9de5-2b05cdcbe5bc","tags":[]},{"id":"poem-c0c302a6370b9f564668f5c1","title":"诉衷情·旋揎玉指著红靴","author":"黄庭坚","dynasty":"宋","verses":["旋揎玉指著红靴。","宛宛斗弯讹。","天然自有殊态，供愁黛、不须多。","分远岫，压横波。","妙难过。","自敧枕处，独倚阑时，不奈颦何。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-823","tags":[]},{"id":"poem-c0e234d9e6b12b19994ab809","title":"赋得残菊","author":"太宗皇帝","dynasty":"唐","verses":["阶兰凝曙霜，岸菊照晨光。","露浓晞晚笑，风劲浅残香。","细叶凋轻翠，圆花飞碎黄。","还持今岁色，复结后年芳。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-4e85cb66-dc1d-42b5-9f64-c5a19b4e9fed","tags":[]},{"id":"poem-c0e42443c3a4dd5041f0927b","title":"看花四绝句  其四","author":"司马光","dynasty":"宋","verses":["南园桃李近方栽，浇水未干花已开。","山果野蔬随分有，交游不厌但频来。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-aaf53b8f-d567-46e5-adfc-3cc480ce0253","tags":[]},{"id":"poem-c0f312a9510774bc4fda8009","title":"桑扈","author":"佚名","dynasty":"先秦","verses":["交交桑扈，有莺其羽。君子乐胥，受天之祜。","交交桑扈，有莺其领。君子乐胥，万邦之屏。","之屏之翰，百辟为宪。不戢不难，受福不那。","兕觥其觩，旨酒思柔。彼交匪敖，万福来求。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-214","tags":[]},{"id":"poem-c0fa49c21348515089e2a596","title":"隠山","author":"释居简","dynasty":"宋","verses":["小岭明明属小支，傍山论价与山违。","巢由去后箕山老，夜夜天云隠少微。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-30ae8a9e-7d64-4fe1-bf53-603d471bb318","tags":[]},{"id":"poem-c10c2c6771fb912f50c7df44","title":"石笋","author":"华镇","dynasty":"宋","verses":["小窗西下碧溪隅，片石干云一笋麤。","苍藓长时斑点露，老藤蟠处节痕纡。","不须凡木装佳色，自有灵花入画图。","为美又应胜竹箭，坚高元与众材殊。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-89127133-aab5-4efd-a95e-002f4791e1a0","tags":[]},{"id":"poem-c115682e9b817583014bfd41","title":"永遇乐·明月如霜","author":"苏轼","dynasty":"宋","verses":["明月如霜，好风如水，清景无限。","曲港跳鱼，圆荷泻露，寂寞无人见。","如三鼓，铿然一叶，黯黯梦云惊断。","夜茫茫，重寻无处，觉来小园行遍。","天涯倦客，山中归路，望断故园心眼。","燕子楼空，佳人何在，空锁楼中燕。","古今如梦，何曾梦觉，但有旧欢新怨。","异时对，黄楼夜景，为余浩叹。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-45","tags":["宋词三百首"]},{"id":"poem-c117118316b948ba23952e77","title":"寄友人","author":"张籍","dynasty":"唐","verses":["忆在江南日，同游三月时。","采茶寻远涧，鬬鸭向春池。","送客沙头宿，招僧竹里碁。","如今各千里，无计得相随。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-a9c7c5b0-202f-42be-876d-62737b4daab0","tags":[]},{"id":"poem-c1197a16bfbf3ff665745635","title":"清平乐·留春不住","author":"王安石","dynasty":"宋","verses":["留春不住。","费尽莺儿语。","满地残红宫锦污。","昨夜南园风雨。","小怜初上琵琶。","晓来思绕天涯。","不肯画堂朱户，春风自在杨花。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-16","tags":["宋词三百首"]},{"id":"poem-c119b3d314a4e5a6e1e35489","title":"剑器近·夜来雨","author":"袁去华","dynasty":"宋","verses":["夜来雨。","赖倩得、东风吹住。","海棠正妖饶处。","且留取。","悄庭户。","试细听、莺啼燕语。","分明共人愁绪。","怕春去。","佳树。","翠阴初转午。","重帘未卷，乍睡起、寂寞看风絮。","偷弹清泪寄烟波，见江头故人，为言憔悴如许。","彩笺无数。","去却寒暄，到了浑无定据。","断肠落日千山暮。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-11","tags":["宋词三百首"]},{"id":"poem-c1270edcc0530ef3106363f4","title":"浣溪沙·访旧伤离欲断魂","author":"李珣","dynasty":"五代","verses":["访旧伤离欲断魂，无因重见玉楼人，六街微雨镂香尘。","早为不逢巫峡梦，那堪虚度锦江春，遇花倾酒莫辞频。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-x-juan.json#record-15","tags":[]},{"id":"poem-c1276a0ddce89a56711466c8","title":"破阵子·四十年来家国","author":"李煜","dynasty":"五代","verses":["四十年来家国，三千里地山河。","凤阁龙楼连霄汉，玉树琼枝作烟萝，几曾识干戈？","一旦归为臣虏，沈腰潘鬓销磨。","最是仓皇辞庙日，教坊犹奏别离歌，垂泪对宫娥。"],"enabled":true,"collection":"南唐二主词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/nantang/poetrys.json#record-35","tags":[]},{"id":"poem-c131375548630200e94c0745","title":"小重山·翡翠林梢青黛山","author":"向","dynasty":"宋","verses":["翡翠林梢青黛山。","小楼新罨画，卷珠帘。","碧纱窗外水挪蓝。","凭栏处，相对玉纤纤。","人散酒阑珊。","夜长都睡皱，唾花衫。","一弯残月下风檐。","凌波去，罗袜步蹁跹。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-185","tags":[]},{"id":"poem-c131f334f8ea044257ed28b9","title":"玉楼春·青钱点水圆荷绿","author":"谢逸","dynasty":"宋","verses":["青钱点水圆荷绿。","解箨新篁森嫩玉。","轻风冉冉楝花香，小雨丝丝梅子熟。","华堂烛烬零金粟。","人在洞天三十六。","昭华吹彻管声寒，声入寿觞红浪蹙。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-631","tags":[]},{"id":"poem-c13234b884afcb8cdd102dbc","title":"南乡子·烟漠漠","author":"李珣","dynasty":"五代","verses":["烟漠漠，雨凄凄，岸花零落鹧鸪啼。","远客扁舟临野渡，思乡处，潮退水平春色暮。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-x-juan.json#record-25","tags":[]},{"id":"poem-c134b3c0fec293e13d5081c9","title":"奉和九日幸临渭亭登高应制得花字","author":"赵彦伯","dynasty":"唐","verses":["九日报仙家，三秋转岁华。","呼鹰下鸟路，戏马出龙沙。","簪挂丹萸蘂，杯浮紫菊花。","所愿同微物，年年共辟邪。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-99297825-8deb-454c-90f2-fea3c6f0890c","tags":[]},{"id":"poem-c13710516273b82b859d2adf","title":"寄寒泉","author":"释居简","dynasty":"宋","verses":["贫则安之岂病焉，乘桴未暇况笺天。","翰林足避将军污，内史灰从廷尉然。","口伐固应无大敌，笔耕元自有丰年。","讲明人爵君何欠，只欠苏司业酒钱。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-f74ea40d-4c10-4074-b241-de1380a11fa2","tags":[]},{"id":"poem-c13dadea791556f1e2f04926","title":"生查子·一岁会盘洲","author":"洪适","dynasty":"宋","verses":["一岁会盘洲，月月生查子。","弟劝复兄酬，举案灯花喜。","曲终人半酣，添酒留罗绮。","车马不须喧，且听三更未。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-731","tags":[]},{"id":"poem-c13f0968f65e2af40a27c6e5","title":"酬衞长林岁日见呈","author":"司空曙","dynasty":"唐","verses":["地暖雪花摧，天春斗柄回。","朱泥一丸药，柏叶万年杯。","旅雁辞人去，繁霜满镜来。","今朝彩盘上，神燕不须雷。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-01c7e7af-0460-4a15-adfe-a0b9b60a6d4e","tags":[]},{"id":"poem-c1444a868c680fdf8b3a7973","title":"偈颂（幷序○序为南岳齐己撰） 六十","author":"居遁","dynasty":"唐","verses":["人天须假像行持，无像无形世岂知？","空生体得岩中坐，华雨由来责见迟。","三乘欲学如斯事，直似空生方始知。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-2a710f0d-6144-49c7-89d6-f04db355383c","tags":["衡山"]},{"id":"poem-c145f9b13d5d787013513091","title":"明堂观礼杂咏十三首 车驾回太庙","author":"王同祖","dynasty":"宋","verses":["瑞霭祥云傍晓开，九重法驾太宫回。","一声静跸千官肃，卫士传呼御座来。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-a3cde1b4-df59-413d-8fdb-c2668cbdabea","tags":[]},{"id":"poem-c148a12cbbc33a85d225470f","title":"九怀·蓄英","author":"王褒","dynasty":"汉","verses":["秋风兮萧萧，舒芳兮振条。","微霜兮眇眇，病殀兮鸣蜩。","玄鸟兮辞归，飞翔兮灵丘。","望谿谷兮滃郁，熊罴兮呴嗥。","唐虞兮不存，何故兮久留？","临渊兮汪洋，顾林兮忽荒。","修余兮袿衣，骑霓兮南上。","乘云兮回回，亹亹兮自强。","将息兮兰皋，失志兮悠悠。","蒶蕴兮霉黧，思君兮无聊。","身去兮意存，怆恨兮怀愁。"],"enabled":true,"collection":"楚辞","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/楚辞/chuci.json#record-43","tags":[]},{"id":"poem-c15f9070b9215220e83e1416","title":"虞美人·芙蓉落尽天涵水","author":"舒亶","dynasty":"宋","verses":["芙蓉落尽天涵水。","日暮沧波起。","背飞双燕帖云寒。","独向小楼东畔、倚阑看。","浮生只合尊前老。","雪满长安道。","故人早晚上高台。","赠我江南春色、一枝梅。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-49","tags":["宋词三百首"]},{"id":"poem-c161eb0c12ae39e0c894d62a","title":"杨夫人挽章二首  其一","author":"李纲","dynasty":"宋","verses":["来嫔初卜凤和鸣，谁谓今闻薤露声。","妇道宜传青史笔，壸仪犹在锦官城。","承家早庆芝兰秀，主馈空余苹藻诚。","念旧二卿情意厚，可堪孤坐想平生。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-c2d84aa1-e82c-4967-889c-61b03b1d9a7b","tags":[]},{"id":"poem-c16e37957da19fe21e5521f1","title":"老将行","author":"王维","dynasty":"唐","verses":["少年十五二十时，步行夺得胡马射。","射杀中山白额虎，肯数邺下黄须儿。","一身转战三千里，一劒曾当百万师。","汉兵奋迅如霹雳，虏骑崩腾畏蒺藜。","衞青不败由天幸，李广无功缘数奇。","自从弃置便衰朽，世事磋跎成白首。","昔时飞箭无全目，今日垂杨生左肘。","路傍时卖故侯瓜，门前学种先生柳。","苍茫古木连穷巷，寥落寒山对虚牖。","誓令疏勒出飞泉，不似颍川空使酒。","贺兰山下阵如云，羽檄交驰日夕闻。","节使三河募年少，诏书五道出将军。","试拂铁衣如雪色，聊持宝劒动星文。","愿得燕弓射天将，耻令越甲鸣吴军。","莫嫌旧日云中守，犹堪一战取功勋。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-d5d66aff-b6ae-48cc-9160-16b096d4ea49","tags":["唐诗三百首","乐府","写人","新乐府辞","赞颂"]},{"id":"poem-c170e234128056e9c5617986","title":"明妃引","author":"孙嵩","dynasty":"宋","verses":["明妃如花颜，高出汉宫右。","可怜君王目，但寄丹青手。","寂寂保孤妍，悠悠成伪丑。","坐此嫁穹庐，流落无时回。","无时回，琵琶未阕边笳催。","哀弦流入千家谱，明妃只作阏支舞。","年年犹借南来风，吹得青青一抔土。","君不见汉家嫁得几娉婷，不闻一一琵琶声。","祸起当年娄敬谬，后人独恨毛延寿。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-6ad0b3b5-e122-42bc-a63f-fa5def4c87d7","tags":[]},{"id":"poem-c188f4fedc16a48b893f63f0","title":"经隐叟","author":"鲍溶","dynasty":"唐","verses":["行蹋门外泉，坐披床上云。","谁将许由事，万古留与君。","虚洞闭金鏁，蠹简藏鸟文。","萝景深的的，蕙风闲薰薰。","余有世上心，此来未及群。","殷勤讳姓名，莫遣樵客闻。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-a5a9e67a-1ff0-483c-bed5-852f681f22d6","tags":[]},{"id":"poem-c189d7f5b68a96ff8b46eba4","title":"题六宜堂","author":"陈造","dynasty":"宋","verses":["昔人厌俗心，宁取无肉瘦。","平时眼为青，绿士须客右。","立节自修竦，适用兼庇覆。","君家所居堂，音响不待叩。","千沟荫百椽，一一渭川秀。","公今王元之，好尚如授受。","记楼赋此堂，异声同一咮。","心谋耳目适，所乐壹能副。","昔人言外意，泥一乃百漏。","拘拘六者间，见未脱科臼。","我此小盘礴，万境欻通透。","徐步寒玉琤，长谣灵籁奏。","主人信清绝，此君旧幽茂。","并策超俗勋，醉墨点衫袖。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-c64854d7-55e2-48fb-8e52-76ea1e65f582","tags":[]},{"id":"poem-c18b75f84e7ac09285b0c439","title":"思帝乡·花花","author":"温庭筠","dynasty":"唐","verses":["花花，满枝红似霞。","罗袖画帘肠断，卓香车。","回面共人闲语，战篦金凤斜。","惟有阮郎春尽，不归家。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-2-juan.json#record-5","tags":[]},{"id":"poem-c1a2b5cb536f7a69d002276f","title":"古镜词上刘侍郎","author":"贯休","dynasty":"唐","verses":["至宝不自宝，照古还照今。","仙人手胼胝，寥泬秋沈沈。","不是十二面，不是百炼金。","若非八彩眉，不可辄照临。","即归玉案头，为君整冠簪。","即居吾君手，照出天下心。","恭闻太宗朝，此镜当宸襟。","六合悬清光，万里无尘侵。","此镜今又出，天地还得一。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-c67a341b-00d8-43fe-b731-49721065beab","tags":[]},{"id":"poem-c1aa25b2e6ddf32afd5712bc","title":"浣溪沙·乌帽斜欹倒佩鱼","author":"孙光宪","dynasty":"五代","verses":["乌帽斜欹倒佩鱼，静街偷步访仙居，隔墙应认打门初。","将见客时微掩敛，得人怜处且先疏，低头羞问壁边书。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-7-juan.json#record-45","tags":[]},{"id":"poem-c1bd1b5f25cf1bfa390ae027","title":"晚春即事","author":"王镃","dynasty":"宋","verses":["云气不分明，天阴忽又晴。","喜凉溪鹊浴，知雨沼蛙鸣。","仙药黄精饭，斋蔬白蕈羹。","惜春吟未就，闲踏落花行。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-8f5c3d21-df66-4404-9ac8-dbfb8b94f2a5","tags":[]},{"id":"poem-c1c1415caee9c23c46f1666a","title":"莲花峰","author":"陈岩","dynasty":"宋","verses":["风动云开净客颜，三千丈石锦烂斑。","淤泥不是花开处，擢出天河绿水间。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-b0e336d3-0fc5-4430-8323-c0531557c4d3","tags":[]},{"id":"poem-c1c227965bae579d85793fb6","title":"菩萨蛮·山城夜半催金柝","author":"纳兰性德","dynasty":"清","verses":["山城夜半催金柝，酒醒孤馆灯花落。","窗白一声鸡，枕函闻马嘶。","门前乌桕树，霜月迷行处。","遥忆独眠人，早寒惊梦频。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-190","tags":[]},{"id":"poem-c1c788149bd1457b350b730a","title":"送从叔赴洪州","author":"李端","dynasty":"唐","verses":["荣家兼佐幕，叔父似还乡。","王粲名虽重，郄超髯未长。","鸣桡过夏口，敛笏见浔阳。","后夜相思处，中庭月一方。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-c98956e6-9415-4374-bfca-925ca2b91243","tags":[]},{"id":"poem-c1d07b2cddcc1935e6da82f1","title":"八声甘州","author":"无名氏《宦门子弟错立身》","dynasty":"元","verses":["子规两三声，劝道不如归去，羁旅伤情。","花残莺老，虚度几多芳春。","家乡万里，烟水万重，奈隔断鳞鸿无处寻。","一身，似雪里杨花飞轻。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-317","tags":[]},{"id":"poem-c1d74737fe42c6db44e1f3da","title":"和江西萧少卿见寄二首  其一","author":"徐铉","dynasty":"宋","verses":["亡羊岐路愧司南，二纪穷通聚散三。","老去何妨从笑傲，病来看欲懒朝参。","离肠似线常忧断，世态如汤不可探。","珍重加餐省思虑，时时斟酒压山岚。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-d0de5eba-2cd6-42c8-91b0-f3553a8eba76","tags":[]},{"id":"poem-c1e0af4802360debbc96dd80","title":"敦煌廿咏（并序） 三、莫高窟咏[二]","author":"敦煌人作品[一]","dynasty":"唐","verses":["雪岭干青汉，云楼架碧空，重开千佛刹[一二]，旁出四天宫。","瑞鸟含珠影，灵花吐蕙藂（丛）。","洗心游胜境，从此去尘蒙。","。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-24f02f29-53d6-4eb3-bfe4-5baa60950a94","tags":[]},{"id":"poem-c1e3a9e4b561d3678fa8e3dd","title":"独不见","author":"胡曾","dynasty":"唐","verses":["玉关一自有氛埃，年少从军竟未回。","门外尘凝张乐榭，水边香灭按歌台。","窗残夜月人何处，帘卷春风燕复来。","万里寂寥音信绝，寸心争忍不成灰。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-35e79af8-d41e-4ad4-949c-83f851a13447","tags":[]},{"id":"poem-c1e57f0914d82fc921332678","title":"鹧鸪天·忆昔彤庭望日华","author":"张孝祥","dynasty":"宋","verses":["忆昔彤庭望日华。","匆匆枯笔梦生花。","郁轮袍曲惭新奏，风送银湾犯斗槎。","追往事，甫新瓜。","飞蓬何事及兰麻。","一江湘水流馀润，十里河堤筑浅沙。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-243","tags":[]},{"id":"poem-c1ec4444fd5c4c76662ed28d","title":"奉和初春幸太平公主南庄应制","author":"李邕","dynasty":"唐","verses":["传闻银汉支机石，复见金舆出紫微。","织女桥边乌鹊起，仙人楼上凤皇飞。","流风入座飘歌扇，瀑水侵阶溅舞衣。","今日还同犯牛斗，乘槎共逐海潮归。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-fe2277d7-42fb-4069-b4d2-c69887a0b629","tags":[]},{"id":"poem-c1ee4e7e11da9d5c7119de39","title":"投赠张端公","author":"孟郊","dynasty":"唐","verses":["君子量不极，胸吞百川流。","嫉邪霜气直，问俗春辞柔。","日户昼辉静，月杯夜景幽。","咏惊芙蓉发，笑激风飙秋。","鸾步独无侣，鹤音仍寡俦。","幸沾分寸顾，散此千万忧。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-3f954ce2-044e-45a3-9c6c-2f90a64718c8","tags":[]},{"id":"poem-c1f35e3a9da8ff8b340c38f4","title":"从军夜次六胡北饮马磨劒石为祝殇辞","author":"李益","dynasty":"唐","verses":["我行空碛，见沙之磷磷，与草之幂幂。","半没胡儿磨劒石，当时洗劒血成川。","至今草与沙皆赤，我因扣石问以言。","水流呜咽幽草根，君宁独不怪阴燐。","吹火荧荧又为碧，有鸟自称蜀帝魂。","南人伐竹湘山下，交根接叶满泪痕。","请君先问湘江水，然我此恨乃可论。","秦亡汉绝三十国，关山战死知何极。","风飘雨洒水自流，此中有冤消不得。","为之弹劒作哀吟，风沙四起云沈沈。","满营战马嘶欲尽，毕昴不见胡天阴。","东征曾吊长平苦，往往睛明独风雨。","年移代去感精魂，空山月暗闻鼙鼓。","秦坑赵卒四十万，未若格鬬伤戎虏。","圣君破胡为六州，六州又尽为胡丘。","韩公三城断胡路，汉甲百万屯边秋。","乃分司空授朔土，拥以玉节临诸侯。","汉为一雪万世讐，我今抽刀勒劒石，告尔万世为唐休。","又闻招魂有美酒，为我浇酒祝东流。","殇为魂兮，可以归还故乡些。","沙场地无人兮，尔独不可以久留。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-7e7eeac9-cf7a-4b57-af7d-60ac5ab60ad3","tags":[]},{"id":"poem-c1f9f2a4c6b08f94815afd3a","title":"洛姝真珠","author":"李贺","dynasty":"唐","verses":["真珠小娘下清廓，洛苑香风飞绰绰。","寒鬓斜钗玉燕光，高楼唱月敲悬珰。","兰风桂露洒幽翠，红弦褭云咽深思。","花袍白马不归来，浓蛾叠柳香唇醉。","金鵞屏风蜀山梦，鸾裾凤带行烟重。","八骢笼晃脸差移，日丝繁散曛罗洞。","市南曲陌无秋凉，楚腰卫鬓四时芳。","玉喉窱窱排空光，牵云曳雪留陆郎。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-4ce0824b-965f-482e-bf01-ce11bb71519a","tags":[]},{"id":"poem-c1fb0d288b67a3de6adcc24a","title":"神功盛德诗  其一","author":"华镇","dynasty":"宋","verses":["茫茫神州，有疆有理。","歼殄豺虎，翦夷荆杞。","人可以群，神获其祀，惟宣祖是畀。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-6504b6ef-3b36-4a9c-ab33-7eab0fa74f4b","tags":[]},{"id":"poem-c2031ccd918499ca6df9448b","title":"幸蜀西至劒门","author":"明皇帝","dynasty":"唐","verses":["劒阁横云峻，銮舆出狩回。","翠屏千仞合，丹嶂五丁开。","灌木萦旗转，仙云拂马来。","乘时方在德，嗟尔勒铭才。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-1373b7fb-a34d-468f-8bc3-127bce69027e","tags":[]},{"id":"poem-c20324f6abe11083d85ddb81","title":"晓起","author":"赵崇鉘","dynasty":"宋","verses":["雨漂窗纸湿成瑕，风压瓷瓶卧枕沙。","晓起无悰饧粥冷，自添新水救梨花。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-6081fc5c-ff29-4bfb-bebc-26b360e6b0d2","tags":[]},{"id":"poem-c215ec445cae8f53720aab6d","title":"送新罗人归本国","author":"刘得仁","dynasty":"唐","verses":["鸡林隔巨浸，一住一年行。","日近国先曙，风吹海不平。","眼穿乡井树，头白渺弥程。","到彼星霜换，唐家语却生。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-6cc338af-cc0a-4023-bef7-ccb1ad77c293","tags":[]},{"id":"poem-c217c4678e1c662c181b903f","title":"偈颂十四首  其五","author":"释印肃","dynasty":"宋","verses":["化彼三千七十士，唯恐迷流增嫉妬。","不患寡而患不均，后代绵绵常贵富。","我道无心粥饭缘，饥餐渴饮全无措。","一家有事百家忧，心浄还如佛浄土。","庐陵米价也寻常，一粒破时全体露。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-29ffdf3d-913a-4d8a-b913-8f1c4d193a2e","tags":[]},{"id":"poem-c2184fe7b7b7503ec85356f7","title":"赠南陵李主簿","author":"曹松","dynasty":"唐","verses":["外邑官同隐，宁劳短吏趋。","看云情自足，爱酒逸应无。","簟席弹碁子，衣裳惹印朱。","仍闻陂水近，亦拟掉菰蒲。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-79b83eff-5da9-4a0f-b98b-a2944af5bffb","tags":[]},{"id":"poem-c21b54c3a17597e6a09bb522","title":"丹青引赠曹将军霸","author":"杜甫","dynasty":"唐","verses":["将军魏武之子孙，于今为庶为清门。","英雄割据虽已矣，文彩风流犹尚存。","学书初学卫夫人，但恨无过王右军。","丹青不知老将至，富贵于我如浮云。","开元之中常引见，承恩数上南熏殿。","凌烟功臣少颜色，将军下笔开生面。","良相头上进贤冠，猛将腰间大羽箭。","褒公鄂公毛发动英姿飒爽来酣战。","先帝天马玉花骢，画工如山貌不同。","是日牵来赤墀下，迥立阊阖生长风。","诏谓将军拂绢素，意匠惨澹经营中。","斯须九重真龙出，一洗万古凡马空。","玉花却在御榻上，榻上庭前屹相向。","至尊含笑催赐金，圉人太仆皆惆怅。","弟子韩干早入室，亦能画马穷殊相。","干惟画肉不画骨，忍使骅骝气凋丧。","将军画善盖有神，必逢佳士亦写真。","即今飘泊干戈际，屡貌寻常行路人。","途穷反遭俗眼白，世上未有如公贫。","但看古来盛名下，终日坎𡒄缠其身。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-13b12259-3750-4c6d-87ee-35283ad63dab","tags":["写人","同情","唐诗三百首","七言古诗","怅惘"]},{"id":"poem-c22c39e7f910c84422f3a1ae","title":"游头陀寺上方","author":"项斯","dynasty":"唐","verses":["高步陟崔嵬，吟闲路惜回。","寺知何代有，僧见梵天来。","暮霭连沙积，余霞徧槛开。","更期招静者，长啸上南台。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-861662ba-6bea-4ab0-aee0-c3fc5b7ffa87","tags":[]},{"id":"poem-c23842c9695a0c034ed68221","title":"同群公秋登琴台","author":"高适","dynasty":"唐","verses":["古迹使人感，琴台空寂寥。","静然顾遗尘，千载如昨朝。","临眺自兹始，群贤久相邀。","德与形神高，孰知天地遥。","四时何倏忽，六月鸣秋蜩。","万象归白帝，平川横赤霄。","犹是对夏伏，几时有凉飙。","燕雀满簷楹，鸿鹄抟扶摇。","物性各自得，我心在渔樵。","兀然还复醉，尚握尊中瓢。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-b86dfe06-639c-446e-ac96-298a1403d16e","tags":[]},{"id":"poem-c249d1c16264954fe6f32033","title":"法曲献仙音·层绿峨峨","author":"王沂孙","dynasty":"宋","verses":["层绿峨峨，纤琼皎皎，倒压波痕清浅。","过眼年华，动人幽意，相逢几番春换。","记唤酒寻芳处，盈盈褪妆晚。","已销黯。","况凄凉、近来离思，应忘却、明月夜深归辇。","荏苒一枝春，恨东风、人似天远。","纵有残花，洒征衣、铅泪都满。","但殷勤折取，自遣一襟幽怨。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-252","tags":["宋词三百首"]},{"id":"poem-c254a0c8c67ae8df02555665","title":"浣溪沙·已惯天涯莫浪愁","author":"纳兰性德","dynasty":"清","verses":["已惯天涯莫浪愁，寒云衰草渐成秋。","漫因睡起又登楼。","伴我萧萧惟代马，笑人寂寂有牵牛，劳人只合一生休。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-145","tags":[]},{"id":"poem-c257af48e13af2c849341dcd","title":"同前","author":"萧德祥《小孙屠》","dynasty":"元","verses":["本官心地，事由公理。","踢脱这些儿，果有阴德处。","(和同前)(梅)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8593","tags":[]},{"id":"poem-c259b1099f0f28d4483e2df4","title":"白莲雨后渐衰","author":"释居简","dynasty":"宋","verses":["晓池芳柄褭残馨，褪雨欹风鹭委翎。","碧展一奁秋练练，似怜玉色镜中零。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-a58a2fcd-82d7-4518-91d9-14f9be83cee1","tags":[]},{"id":"poem-c25a5bc52c7163bfdc69714a","title":"哭郎著作","author":"郑愔","dynasty":"唐","verses":["诗礼康成学，文章贾谊才。","巳年人得梦，庚日鸟为灾。","书草藏天阁，琴声入夜台。","荒阶罗驳藓，虚座网浮埃。","白马宾徒散，青乌陇隧开。","空怜门下客，怀旧几迟回。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-01c3c86a-f92b-4ec3-93e5-5251f52137c3","tags":[]},{"id":"poem-c25cc8af7074fa8d0a556cdf","title":"卜算子·寒透小窗纱","author":"黄公度","dynasty":"宋","verses":["寒透小窗纱，漏断人初醒。","翡翠屏间拾落钗，背立残釭影。","欲去更踟蹰，离恨终难整。","陇首流泉不忍闻，月落双溪冷。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-435","tags":[]},{"id":"poem-c26810268365ed6b8e218349","title":"示后学偈","author":"令参","dynasty":"唐","verses":["入门须有语，不语病拪芦。","应须满口道，莫教带有无。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-36caff5c-18c5-4af8-84fe-74110cf3b04c","tags":[]},{"id":"poem-c26a8337b4ef63e48f2dde45","title":"踏莎行·祖席离歌","author":"晏殊","dynasty":"宋","verses":["祖席离歌，长亭别宴。","香尘已隔犹回面。","居人匹马映林嘶，行人去棹依波转。","画阁魂消，高楼目断。","斜阳只送平波远。","无穷无尽是离愁，天涯地角寻思遍。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-165","tags":["宋词三百首"]},{"id":"poem-c2717d8897b01e323dfc5440","title":"赠李司议","author":"张籍","dynasty":"唐","verses":["汉庭谁问投荒客，十载天南着白衣。","秋草茫茫恶谿路，岭头遥送北人稀。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-c0b1d427-649a-4860-aa54-589b206d13aa","tags":[]},{"id":"poem-c27389280cf6d35902dfc51a","title":"凤凰台上忆吹箫·香冷金猊","author":"李清照","dynasty":"宋","verses":["香冷金猊，被翻红浪，起来人未梳头。","任宝奁闲掩，日上帘钩。","生怕闲愁暗恨，多少事、欲说还休。","今年瘦，非干病酒，不是悲秋。","明朝，这回去也，千万遍阳关，也即难留。","念武陵春晚，云锁重楼。","记取楼前绿水，应念我、终日凝眸。","凝眸处，从今更数，几段新愁。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-200","tags":["宋词三百首"]},{"id":"poem-c27417bd2b90bf392b91a78f","title":"郊庙歌辞 祭神州乐章 迎神","author":"不详","dynasty":"唐","verses":["黄舆厚载，赤寰归德。","含育九区，保安万国。","诚敬无怠，禋祀有则。","乐以迎神，其仪不忒。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-c7b4ab4c-0e3f-4fa0-b1e1-09b4e98fc4ac","tags":[]},{"id":"poem-c2778a9aa1bb573b5fecf661","title":"题僧堂前梁","author":"义存","dynasty":"唐","verses":["今朝不保明朝，常作千载遮头。","（以上均见《卍续藏经》本《雪峰真觉禅师语录》卷下。","是书附北宋王随、孙觉等人序。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-7f8c1f1f-a11d-4d4c-b7b8-2f7c31440869","tags":[]},{"id":"poem-c283b38b7c8219e9320da680","title":"满庭芳·欲买庐山","author":"晁补之","dynasty":"宋","verses":["欲买庐山，山前三亩，小桥横过松间。","变名吴市，谁认旧容颜。","最好栖贤峡外，应自此、都隔尘寰。","人稀到，壶中化国，光景更堪闲。","无心，求至道，柴门闭了，饱睡甘飡。","幸儿成孙长，为扫家山。","若问它年归去，蓦地也、双桨来还。","愁难舍，清风万壑，高处正跻攀。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-182","tags":["庐山"]},{"id":"poem-c2869cc2dbd483201f8e36f0","title":"怨情","author":"李白","dynasty":"唐","verses":["美人卷珠帘，深坐颦蛾眉。","但见泪痕湿，不知心恨谁。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-22e72306-f41c-4621-a925-83bab7f9d76e","tags":["唐诗三百首","五言绝句","女子"]},{"id":"poem-c287be14d0ff4ba2172ea5ea","title":"书菊磵屏兰","author":"释居简","dynasty":"宋","verses":["欲酬天问些灵均，九畹归来活写真。","采笔不知春去后，自芳元不为无人。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-7119d83d-aceb-47ec-8dbe-226daacc9d81","tags":[]},{"id":"poem-c296503edea1d898b647c613","title":"送韩玉汝太博出守洋州","author":"苏颂","dynasty":"宋","verses":["州封繁会逼梁嶓，继世为藩盛事多。","遗德在人棠蔽芾，旧游经眼树婆娑。","春生剑外壶浆溢，花满褒中驷马过。","父老逢迎应善祝，缁衣将入郑风歌。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-b8110d05-a66e-4546-99c2-42315273a1c5","tags":[]},{"id":"poem-c29683be38387b67fbab7c10","title":"送僧","author":"王鼎","dynasty":"唐","verses":["孤云踪迹都无定，出个青山入个山。","（均见周校本《诗话总龟》卷四六引《雅言杂载》）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-5008271e-e2dc-4a64-bb71-5a05be914a16","tags":[]},{"id":"poem-c29690f311190bf9ce9708a8","title":"送张舍人佐江州同薛璩十韵","author":"王维","dynasty":"唐","verses":["束带趋承明，守官唯谒者。","清晨听银蚪，薄暮辞金马。","受辞未尝易，当是方知寡。","清范何风流，高文有风雅。","忽佐江上州，当自浔阳下。","逆旅到三湘，长途应百舍。","香炉远峰出，石镜澄湖泻。","董奉杏成林，陶潜菊盈把。","范蠡常好之，庐山我心也。","送君思远道，欲以数行洒。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-4b2d6332-f295-45b4-9b7b-fefbea9fa4fa","tags":["庐山"]},{"id":"poem-c29cdbeec21063d7aaf8b489","title":"虞美人·高楼远阁花飞遍","author":"方千里","dynasty":"宋","verses":["高楼远阁花飞遍。","急雨捎池面。","けけ杨柳不知门。","多少乱莺啼处、暮烟昏。","银钩小字题芳絮。","宛转回文语。","可怜单枕梦行云。","肠断江南千里、未归人。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-559","tags":[]},{"id":"poem-c2a268092dd562fe21476cf7","title":"咏史诗 瑶池","author":"胡曾","dynasty":"唐","verses":["阿母瑶池宴穆王，九天仙乐送琼浆。","漫矜八骏行如电，归到人间国已亡。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-d639934c-e35a-49a8-972f-5b1b22d0e2b9","tags":[]},{"id":"poem-c2a625334eb89372febdaf99","title":"洞仙歌·冰肌玉骨","author":"苏轼","dynasty":"宋","verses":["冰肌玉骨，自清凉无汗。","水殿风来暗香满。","绣帘开、一点明月窥人，人未寝、枕钗横鬓乱。","起来携素手，庭户无声，时见疏星渡河汉。","试问夜如何，夜已三更，金波淡、玉绳低转。","但屈指、西风几时来，又不道、流年暗中偷换。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-43","tags":["宋词三百首"]},{"id":"poem-c2ad30db403d8f34ffe57ce5","title":"阁皂山","author":"徐铉","dynasty":"宋","verses":["殿影高低云掩映，松阴缭绕步徘徊。","从今莫厌簪裾累，不是乘轺不得来。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-abd3a148-7f23-402b-ac47-8c938d20292f","tags":[]},{"id":"poem-c2afa023df1939eb1326bd30","title":"北得胜令","author":"徐田臣《杀狗记》","dynasty":"元","verses":["化一狗，假如人，撇他在后园门。","孙员外匆忙见，料无能辨假真！杀人，教他结义的难承认，销魂，须知是亲人到底亲。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-1891","tags":[]},{"id":"poem-c2b21323cf3409f95373d31a","title":"孤寝怨","author":"崔珪","dynasty":"唐","verses":["征戍动经年，含情拂玳筵。","花飞织锦处，月落捣衣边。","灯暗愁孤坐，床空怨独眠。","自君辽海去，玉匣闭春弦。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-dfc7ba4a-f19d-48d3-8a9b-5b4f47a0b880","tags":[]},{"id":"poem-c2b7a22da72210f791d74132","title":"采桑子·桃花羞作无情死","author":"纳兰性德","dynasty":"清","verses":["桃花羞作无情死，感激东风，吹落娇红，飞入窗间伴懊侬。","谁怜辛苦东阳瘦，也为春慵，不及芙蓉，一片幽情冷处浓。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-198","tags":[]},{"id":"poem-c2d46cf07a8d915a86eecfe4","title":"湘灵鼓瑟","author":"陈季","dynasty":"唐","verses":["神女泛瑶瑟，古祠严野亭。","楚云来泱漭，湘水助清泠。","妙指微幽契，繁声入杳冥。","一弹新月白，数曲暮山青。","调苦荆人怨，时遥帝子灵。","遗音如可赏，试奏为君听。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-df64caa8-cae5-4863-b8ce-d499357b1dab","tags":[]},{"id":"poem-c2d9c758688d48153e8f4702","title":"子夜吴歌 冬歌","author":"李白","dynasty":"唐","verses":["明朝驿使发，一夜絮征袍。","素手抽针冷，那堪把剪刀。","裁缝寄远道，几日到临洮。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-35319d7e-9cf6-43b0-bfa3-991cf82a49f9","tags":["思念","清商曲辞","妇女","冬天","唐诗三百首","乐府"]},{"id":"poem-c2ecdd33a94a1a141db2cbfd","title":"春初送吕补阙往西岳勒碑得云字","author":"孙逖","dynasty":"唐","verses":["刻石记天文，朝推谷子云。","箧中缄圣札，岩下揖神君。","语别梅初艳，为期草欲薰。","往来春不尽，离思莫氛氲。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-4fa85826-eacc-420c-971e-9ce5f3d353ed","tags":["华山"]},{"id":"poem-c2f0aa975b5cd2d9f5b80300","title":"滴溜子","author":"施惠《幽闺记》","dynasty":"元","verses":["(外)我有一个道理：明日里，明日里，小设酒筵；媒婆去，媒婆去，传语状元，既然他心中不愿，如何强逼他谐缱绻。","(老旦)既如此，你请他来怎么？(外)请来饮酒之间呵，先教他妹子在堂前，隔帘认看。","(老旦)此计甚好。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-3101","tags":[]},{"id":"poem-c2f2f8be024ba399773ec923","title":"渔家傲·八月微凉生枕簟","author":"欧阳修","dynasty":"宋","verses":["八月微凉生枕簟。","金盘露洗秋光淡。","池上月华开宝鉴。","波潋滟。","故人千里应凭槛。","蝉树无情风苒苒。","燕归碧海珠帘揜。","沈臂冒霜潘鬓减。","愁黯黯。","年年此夕多悲感。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-714","tags":[]},{"id":"poem-c2fdb4b137f99a51bfe579b3","title":"·","author":"本先","dynasty":"唐","verses":["。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-01ad1311-3f37-41a0-9bb5-e7d489782d8a","tags":[]},{"id":"poem-c300061b0fcd7f87a8c5bdea","title":"·","author":"刘蜕","dynasty":"唐","verses":["。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-f9b6c7ee-ca67-4998-baab-4dd1d5ccf50f","tags":[]},{"id":"poem-c300c317ef07b921abcf6677","title":"春秋战国门 平公","author":"周昙","dynasty":"唐","verses":["鸿鹄轻腾万里高，何殊朝野得贤豪。","能知翼戴穹苍力，不是蒙茸腹背毛。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-5b8e9657-45ed-46d5-8a0b-f579da9f8f84","tags":[]},{"id":"poem-c3107442","title":"江南","author":"佚名","dynasty":"汉","verses":["江南可采莲，莲叶何田田。","鱼戏莲叶间。","鱼戏莲叶东，鱼戏莲叶西。","鱼戏莲叶南，鱼戏莲叶北。"],"enabled":true,"collection":"历代名篇","source":"《乐府诗集》相和歌辞《江南》。","tags":["乐府","采莲"]},{"id":"poem-c31676510473c4926c8c5d4c","title":"胡丈广仲与范伯崇自岳市来同登绝顶举酒极谈得闻比日讲论之乐","author":"张栻","dynasty":"宋","verses":["久憩珠林寺，高轩自远来。","携朋上乔岳，载酒到琼台。","论道吟心乐，吟诗笑眼开。","遥观松柏树，风韵有余哀。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-fc875ad1-9ea2-4adb-b655-1a53caaf4f16","tags":[]},{"id":"poem-c319eaa8a5190a2753eb45d0","title":"重入洛阳东门","author":"李绅","dynasty":"唐","verses":["商颜重命伊川叟，时事知非入洛人。","连野碧流通御苑，满阶秋草过天津。","每惭清秩容衰齿，犹有华簪寄病身。","驱马独归寻里巷，日斜行处旧红尘。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-6bea3434-7a5a-4321-bc84-d20b29627ff6","tags":[]},{"id":"poem-c32caa2d8b48cf0bc07b910c","title":"奉和春日幸望春宫","author":"郑愔","dynasty":"唐","verses":["晨跸凌高转翠旌，春楼望远背朱城。","忽排花上游天苑，却坐云边看帝京。","百草香心初罥蝶，千林嫩叶始藏莺。","幸同葵藿倾阳早，愿比盘根应候荣。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-6d003eb8-81c0-44f2-947e-de5b97164299","tags":[]},{"id":"poem-c32e2e2a849f6e8df43eba9e","title":"伐木","author":"佚名","dynasty":"先秦","verses":["伐木丁丁，鸟鸣嘤嘤。出自幽谷，迁于乔木。嘤其鸣矣，求其友声。","相彼鸟矣，犹求友声。矧伊人矣，不求友生？神之听之，终和且平。","伐木许许，酾酒有藇！既有肥羜，以速诸父。宁适不来，微我弗顾。","于粲洒扫，陈馈八簋。既有肥牡，以速诸舅。宁适不来，微我有咎。","伐木于阪，酾酒有衍。笾豆有践，兄弟无远。民之失德，干糇以愆。","有酒湑我，无酒酤我。坎坎鼓我，蹲蹲舞我。迨我暇矣，饮此湑矣。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-164","tags":[]},{"id":"poem-c32ee97789f778aac22fa597","title":"驻马摘金桃","author":"刘唐卿《白兔记》","dynasty":"元","verses":["他本是豪门，住在沙陀小李村。","我与他公公来往，与我家中有些薄亲。","他暂时落薄暂时贫，领归来自然依本分。","何故怒生嗔？交他进也无门，退也无门，全不有大人苦乐不均。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8831","tags":[]},{"id":"poem-c33160bd7e65fce3e2073ef9","title":"江行无题一百首 三十","author":"钱珝","dynasty":"唐","verses":["渐觉江天远，难逢故国书。","可能无往事，空食鼎中鱼。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-84fe859f-a505-42d7-8052-a4ff8e067c7d","tags":[]},{"id":"poem-c33658b32951a90f79d8d2a7","title":"与丘程凌林四君同赋食河豚","author":"苏颂","dynasty":"宋","verses":["水族诚万种，兹鱼非众俦。","形厖而味异，名与畜豕侔。","江南春风和，乘时溯江流。","贪婪尔之能，腥臊固相投。","膨膨逞怒腹，骈骈竞尖头。","靡因梁笱获，谩污筌饵求。","虚传百金贵，不充四时羞。","假以姜桂芼，荐之尊俎酬。","饱饫有奚适，包藏乃为忧。","嗟予鄙异食，顾此偏憎尤。","河鲂风陈诗，虾蟆讥柳州。","腊毒戒厚味，兹言实嘉谋。","盍投会稽犗，更垂渭滨钩。","一钓蓬山鼇，复连东海鳅。","割鲜轻屠龙，和羹小函牛。","谁同厌若鱼，何必夸食䲡。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-f88dcdaf-808e-4c9b-9494-6cf7fdb40eb7","tags":[]},{"id":"poem-c33874e00b965e69faa33b70","title":"芙蓉楼送辛渐二首 一","author":"王昌龄","dynasty":"唐","verses":["寒雨连天夜入湖，平明送客楚山孤。","洛阳亲友如相问，一片冰心在玉壶。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-090b7792-2942-4f3c-a34d-caccd066c76f","tags":["唐诗三百首","写雨","抒情","送别","七言绝句","雨","六年级下册","小学古诗"]},{"id":"poem-c33a1062b371b1dfc104cf15","title":"谒金门·秋已暮","author":"牛希济","dynasty":"五代","verses":["秋已暮，重叠关山岐路。","嘶马摇鞭何处去，晓禽霜满树。","梦断禁城神鼓，泪滴枕檀无数。","一点凝红和薄雾，翠蛾愁不语。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-5-juan.json#record-43","tags":[]},{"id":"poem-c33b55936f792a80a87996b2","title":"病后作","author":"澹交","dynasty":"唐","verses":["未得忘身法，此身终未安。","病肠犹可洗，瘦骨不禁寒。","药少心情饵，经无气力看。","悠悠片云质，独对夕阳残。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-99c53029-b8af-449e-9b67-630053e36683","tags":[]},{"id":"poem-c345157677e54697a36acbce","title":"菩萨蛮·双双紫燕来华屋","author":"蔡伸","dynasty":"宋","verses":["双双紫燕来华屋。","雨馀芳草池塘绿。","一夜摆花风。","莺花满树红。","杯深君莫诉。","醉袖歌金缕。","无奈惜花心。","老来情转深。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-983","tags":[]},{"id":"poem-c34e07c727a5684f812db98c","title":"挽傅仲温","author":"华镇","dynasty":"宋","verses":["人是南州老，家传北地雄。","忽骑箕尾去，不待大丹功。","华屋闲歌席，长杨惨暮风。","已符同穴契，宁复念孤桐。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-b52347f9-9f61-4421-92b1-b5cb115dbc12","tags":[]},{"id":"poem-c350a0c772c0ecf0dc68ba35","title":"晨起三首  其二","author":"赵文","dynasty":"宋","verses":["山寒日不光，举目断人肠。","儿童莫问路，怕是小筼筜。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-413aa8e9-a874-48f3-b5e8-1cda86815c89","tags":[]},{"id":"poem-c3599e07155b76b4bcc42dc0","title":"踏莎行·堪笑山中","author":"张抡","dynasty":"宋","verses":["堪笑山中，春来风景。","一声啼鸟烟林静。","山泉风暖奏笙簧。","山花雨过开云锦。","短棹桃溪，瘦藤兰径。","独来独往乘幽兴。","韶光回首即成空，及时乐取逍遥性。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-937","tags":[]},{"id":"poem-c35e1f946753b68a0dbe5bfa","title":"闲园书事招畅当","author":"司空曙","dynasty":"唐","verses":["闻蝉昼眠后，欹枕对蓬蒿。","羸病嬾寻戴，田园方咏陶。","傍簷虫挂静，出树蝶飞高。","惆怅临清镜，思君见鬓毛。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-8f23af48-ed87-40b3-bbfd-2824769aa0ae","tags":[]},{"id":"poem-c35f97c0f0006437d0de05ae","title":"郊庙歌辞 祀九宫贵神乐章 豫和 四","author":"不详","dynasty":"唐","verses":["夜如何其，明星煌煌。","天清容卫，露结坛场。","树羽幢幢，佩玉锵锵。","凝精驻目，瞻望神光。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-a859f0e3-355f-4385-bde8-1c793381a587","tags":[]},{"id":"poem-c361fed1c68f9c9b8e35d4fb","title":"即事三首  其一","author":"李纲","dynasty":"宋","verses":["宾江两岸木绵飞，负郭家家熟荔枝。","瘴雨蛮烟已萧瑟，可堪梅子欲黄时。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-a6d0e139-e902-49d8-b532-bdddebc3e117","tags":[]},{"id":"poem-c3641a4de01897a843e4b94a","title":"偈颂十四首  其九","author":"释印肃","dynasty":"宋","verses":["心月孤圆时，光非十五六。","迷者以圆观，智者应妙触。","印危崖，鉴川陆，一性圆通无委曲。","了非心外逐尘缘，下坂不走天然速。","谁道速，有佛之处不得住，无佛之处一时足。","时来铁解放光明，运至石头成白玉。","幸逢施主大开张，古佛慧命汝今续。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-dbc161ee-1b4e-407a-8762-748d6195f607","tags":[]},{"id":"poem-c3645c52dfa73b5812e2a0ec","title":"奉赠太常张卿二十韵","author":"杜甫","dynasty":"唐","verses":["方丈三韩外，昆仑万国西。","建标天地阔，诣绝古今迷。","气得神仙迥，恩承雨露低。","相门清议众，儒术大名齐。","轩冕罗天阙，琳琅识介珪。","伶官诗必诵，夔乐典犹稽。","健笔凌鹦鹉，铦锋莹䴙鹈。","友于皆挺拔，公望各端倪。","通籍逾青琐，亨衢照紫泥。","灵虬传夕箭，归马散霜蹄。","能事闻重译，嘉谟及远黎。","弼谐方一展，班序更何跻。","适越空颠踬，游梁竟惨凄。","谬知终画虎，微分是醯鸡。","萍泛无休日，桃阴想旧蹊。","吹嘘人所羡，腾跃事仍暌。","碧海真难涉，青云不可梯。","顾深慙锻炼，才小辱提携。","槛束哀猨叫，枝惊夜鹊栖。","几时陪羽猎，应指钓璜溪。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-bc6d843e-5cf3-4ecb-ab77-d69c7f653445","tags":[]},{"id":"poem-c36532e38413664db0fd5668","title":"红窗听·记得香闺临别语","author":"晏殊","dynasty":"宋","verses":["记得香闺临别语。","彼此有、万重心诉。","淡云轻霭知多少，隔桃源无处。","梦觉相思天欲曙。","依前是、银屏画烛，宵长岁暮。","此时何计，托鸳鸯飞去。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-461","tags":[]},{"id":"poem-c3696b295edbf58a3a124f75","title":"满江红","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["拚此身来，早去跳江心，捞明月。","［下］。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8202","tags":[]},{"id":"poem-c36c17b2073e87523bb0c1c6","title":"落帽山","author":"华镇","dynasty":"宋","verses":["落帽山头雨脚长，消愁还是感河阳。","劳歌不解凄凉意，小饮难投酩酊乡。","共恨今秋辜彩菊，相期来岁沃霞觞。","须知四美人间少，一笑千金未易偿。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-8d735394-eae9-4ea2-96ec-b4b71aea0cb8","tags":[]},{"id":"poem-c36f14fddab87bbf0d5acf2c","title":"无将大车","author":"佚名","dynasty":"先秦","verses":["无将大车，祇自尘兮。无思百忧，祇自疧兮。","无将大车，维尘冥冥。无思百忧，不出于颎。","无将大车，维尘雍兮。无思百忧，祇自重兮。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-205","tags":[]},{"id":"poem-c3772f26118b9dca61935155","title":"清平乐·青陵蝶梦","author":"纳兰性德","dynasty":"清","verses":["青陵蝶梦，倒挂怜么凤。","退粉收香情一种，栖傍玉钗偷共。","愔愔镜阁飞蛾，谁传锦字秋河。","莲子依然隐雾，菱花暗惜横波。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-162","tags":[]},{"id":"poem-c37f7568d506351577a7a511","title":"凤泉初月","author":"释居简","dynasty":"宋","verses":["一痕隠隠介亭西，庾亮楼头未醉时。","多是团团深夜看，可曾见此巧如眉。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-d519f224-16fc-4e9d-97d5-1123bb831b2d","tags":[]},{"id":"poem-c385cc6f6f4679ea4fe01ad8","title":"献襄阳于大夫","author":"孟郊","dynasty":"唐","verses":["襄阳青山郭，汉江白铜堤。","谢公领兹郡，山水无尘泥。","铁马万霜雪，绛旗千虹霓。","风漪参差泛，石板重叠跻。","旧泪不复堕，新欢居然齐。","还畊竟原野，归老相扶携。","物色增暧暧，寒芳更萋萋。","渊清有遐略，高躅无近蹊。","即此富苍翠，自然引翔栖。","曩游常抱忆，夙好今尚暌。","愿言从逸辔，暇日凌清溪。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-4bd8ab64-ee6d-4ba5-938c-85650dace115","tags":[]},{"id":"poem-c387d81ab8e9a6bcd7eb9a7a","title":"神弦别曲","author":"李贺","dynasty":"唐","verses":["巫山小女隔云别，春风松花山上发。","绿盖独穿香径归，白马花竿前孑孑。","蜀江风澹水如罗，堕兰谁泛相经过。","南山桂树为君死，云衫浅汚红脂花。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-0d28db5a-f66d-45e8-abbc-babe8dde823c","tags":[]},{"id":"poem-c3b5b9269497a6c4c5274f2e","title":"小游仙诗九十八首 二十一","author":"曹唐","dynasty":"唐","verses":["月影悠悠秋树明，露吹犀簟象床轻。","嫔妃久立帐门外，暗笑夫人推酒声。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-1fede091-6a7f-4bba-92bc-fde38ab07b0a","tags":[]},{"id":"poem-c3cec765f2d6fae4c3dcbf5e","title":"次王彦昭寄苏景谟青社园亭韵二首  其一","author":"刘跂","dynasty":"宋","verses":["丞掾分曹付旧规，翩翩文彩妙当时。","何人误读雌霓赋，他日真成幼妇碑。","曲水流觞如故事，平山行乐有新诗。","春来想见棠阴盛，可但诗人别后思。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-00d6e6a6-9c9f-416c-b45f-52c002dff425","tags":[]},{"id":"poem-c3cfff1055a2d866e433ffe4","title":"梦江南·梳洗罢","author":"温庭筠","dynasty":"唐","verses":["梳洗罢，独倚望江楼。","过尽千帆皆不是，斜晖脉脉水悠悠，肠断白苹洲。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-2-juan.json#record-7","tags":[]},{"id":"poem-c3da9e87504b1c853ad584f4","title":"云外峰","author":"陈岩","dynasty":"宋","verses":["耸入云端一壁青，地高转步即天京。","有人著屐冲云去，但见云从脚下生。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-81026cae-0fdb-4856-ae1a-c7a86d1e0155","tags":[]},{"id":"poem-c3dc62684eadb13f96612dd3","title":"油葫芦","author":"杨景贤","dynasty":"元","verses":["王母仙衣无分着，金灿烂光闪烁，多管是天孙巧织紫霞绡。","(行者云)银丝帽子，丑的带了便可喜。","(金女云)大圣，你且先戴一戴。","你去玉皇宫偷得银丝帽，抵多少琼林宴颁赐金花诰。","(行者云)左右的，与我照管前后洞门，休放闲神上来。","(金女唱)他耍性儿乖，劣性儿乔，则恐怕筵间引得天兵到，因此上摆布一周遭。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-10302","tags":[]},{"id":"poem-c3de3bdb25a971188b5a781f","title":"公刘","author":"佚名","dynasty":"先秦","verses":["笃公刘，匪居匪康。乃埸乃疆，乃积乃仓；乃裹糇粮，于橐于囊。","思辑用光，弓矢斯张；干戈戚扬，爰方启行。","笃公刘，于胥斯原。既庶既繁，既顺乃宣，而无永叹。陟则在𪩘，复降在原。何以舟之？维玉及瑶，鞞琫容刀。","笃公刘，逝彼百泉。瞻彼溥原，乃陟南冈。乃觏于京，京师之野。","于时处处，于时庐旅，于时言言，于时语语。","笃公刘，于京斯依。跄跄济济，俾筵俾几。既登乃依，乃造其曹。","执豕于牢，酌之用匏。食之饮之，君之宗之。","笃公刘，既溥既长。既景乃冈，相其阴阳，观其流泉。其军三单，度其隰原。彻田为粮，度其夕阳。豳居允荒。","笃公刘，于豳斯馆。涉渭为乱，取厉取锻，止基乃理。爰众爰有，夹其皇涧。溯其过涧。止旅乃密，芮鞫之即。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-249","tags":[]},{"id":"poem-c3e38a520f6ce55c9a42ad28","title":"油葫芦","author":"杨景贤","dynasty":"元","verses":["你道是万事无过酒破除，你不曾读《大禹谟》？禹恶旨酒而好善言，进来的美酒禁入皇都。","你今日白衣应举思高步，恰便似黄鹂出谷迁乔木。","今日受三品职，全凭你满腹书。","布衣中跳到洪州路，倒不如借住在步兵厨。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-7938","tags":[]}];
